const top_rengar = {
  champion: '렝가',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '1~2레벨에는 가렌의 (P)\'인내심\' 회복을 막기 위해 짧게 툭 치고 빠지는 것이 좋아요. 수풀을 활용해 (P)\'보이지 않는 포식자\'로 도약하며 (Q)\'포악함\'으로 짧게 때리고, 가렌이 (Q)\'결정타\'로 반격하기 전에 거리를 벌리세요. 가렌이 (Q)\'결정타\'를 사용하면 이동 속도가 빨라지니 무리하게 붙지 마세요.', lv3: '가렌의 (Q)\'결정타\'는 걸려 있는 둔화를 제거하니, (E)\'올가미 투척\'은 (Q)\'결정타\'가 빠진 뒤에 맞히거나 최대 야성의 속박으로 쓰세요. 가렌이 (W)\'용기\'를 사용해 보호막을 얻으면 받는 피해량이 감소하니, (W)\'용기\'가 끝난 뒤에 (Q)\'포악함\'을 섞어 딜교환을 하세요. (E)\'심판\'이 돌아갈 때는 가렌의 회전 범위 안에서 빠르게 벗어나 (W)\'전투의 포효\'로 피해를 회복하며 거리를 조절하세요.', lv6: '(R)\'사냥의 전율\'로 진입해 가렌의 방어력을 깎고 (E)\'올가미 투척\'을 맞힌 뒤 (Q)\'포악함\'을 이어 빠르게 몰아붙이세요. 가렌의 (R)\'데마시아의 정의\'는 내가 잃은 체력에 비례한 고정 피해를 입히니, 체력이 낮을 때는 가렌의 사거리 안에 오래 머물지 마세요. (P)\'인내심\' 때문에 가렌은 피해를 받지 않으면 회복하니, 수풀을 확보해 정글러와 함께 연속으로 압박하세요.', item: '첫 코어로 몰락한 왕의 검을 가면 가렌의 높은 체력을 깎기에 좋고 생명력 흡수로 유지력도 챙길 수 있어요. 신발은 가렌의 기본 공격 피해를 줄여 주는 판금 장화를 선택하세요.', spell: '점멸과 점화를 추천해요. 점화로 가렌의 (P)\'인내심\' 회복을 억제하고 체력이 낮은 가렌을 빠르게 처치하세요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 멀리서 견제하며 골드를 챙기니 수풀에 숨어 거리 조절을 하세요. 수풀에서 (P)\'보이지 않는 포식자\'를 통해 도약하며 짧게 공격하고 빠지는 방식으로 대응하세요. 근접 평타에 (P)\'불의 심판\' 불이 붙어 피해를 입히니 오래 붙어 있지 말고 빠르게 치고 나가세요.', lv3: '(E)\'올가미 투척\'을 맞춰 속박시킨 뒤 (Q)\'포악함\'으로 몰아쳐야 하지만 갱플랭크가 (W)\'괴혈병 치료\'로 즉시 풀고 체력을 채울 수 있어요. 상대의 (W)\'괴혈병 치료\'가 빠진 것을 확인한 뒤 진입해 야성 강화 공격을 쏟아내세요. 발밑에 (E)\'화약통\'이 깔려 있다면 터질 때 둔화가 걸리니 통 위치를 피해 도약하세요.', lv6: '(R)\'사냥의 전율\'을 켜서 위장 상태로 접근해 방어력을 깎고 도약하면 순식간에 체력을 뺄 수 있어요. 갱플랭크가 (R)\'포탄 세례\'를 사용해 둔화를 걸면 추격이 어려우니 장판 밖에서 진입 경로를 잡으세요. 라인을 당겨서 받으면 갱플랭크가 (Q)\'혀어어어업상\'으로 파밍하기 편해지니 적절히 밀고 당기며 정글의 개입을 노리세요.', item: '굶주린 히드라를 첫 코어로 선택해 생명력 흡수와 공격력을 챙기세요. 신발은 갱플랭크의 근접 기본 공격 피해를 줄여 주는 판금 장화가 좋고, 스킬 피해는 줄여 주지 못한다는 점을 기억하세요.', spell: '점멸과 점화를 추천해요. 갱플랭크가 (W)\'괴혈병 치료\'로 체력을 회복하는 것을 억제하고 킬각을 잡기 위해서예요.' },
    '그라가스': { lv1: '그라가스가 (Q)\'술통 굴리기\'로 둔화를 걸며 견제하니 술통이 터지는 위치를 피해 막타를 챙기세요. 수풀에 숨어 (P)\'보이지 않는 포식자\'를 활용해 짧게 딜교환을 시도하며 체력을 관리해요. 1~2레벨에는 무리하게 싸우기보다 수풀을 이용해 거리 조절을 하며 파밍에 집중하세요.', lv3: '그라가스의 (E)\'몸통 박치기\'가 빠진 것을 확인한 뒤에 (E)\'올가미 투척\'을 맞히며 다가가세요. 그라가스가 (W)\'취중 분노\'를 사용해 받는 피해를 줄이는 동안에는 억지로 들어가기보다 기다려요. (Q)\'포악함\'을 섞은 공격으로 빠르게 딜교환을 마친 뒤 수풀로 숨어 빠져나오세요.', lv6: '(R)\'사냥의 전율\'로 방어력을 감소시키며 진입하면 (Q)\'포악함\'과 연계해 킬각을 잡기 쉬워요. 그라가스가 (R)\'술통 폭발\'로 밀어낼 수 있으니 스킬을 사용하는 위치를 신중하게 잡아야 해요. 정글러가 근처에 있다면 수풀을 통해 시야를 확보하며 압박을 이어가세요.', item: '굶주린 히드라를 첫 코어로 가서 생명력 흡수로 유지력을 높이세요. 신발은 그라가스의 마법 피해와 군중 제어 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 그라가스의 (P)\'서비스 시간\' 체력 회복을 억제하여 확실하게 마무리할 수 있어요.' },
    '그웬': { lv1: '1~2레벨에는 (P)\'가위 난도질\'로 인한 그웬의 체력 회복이 강력하니 긴 평타 교환은 피하세요. 수풀을 활용해 (Q)\'포악함\'을 사용한 도약 공격으로 짧게 딜교환을 하고 빠지는 것이 좋아요. 그웬이 (Q)\'싹둑싹둑!\'을 쓰며 다가오면 거리를 유지하며 대응하세요.', lv3: '그웬이 (W)\'신성한 안개\'를 사용하면 대상 지정 스킬은 막히지만 (E)\'올가미 투척\'은 안개 속으로 날아가 그대로 적중해요. 그웬의 (E)\'돌격가위\'가 빠진 시점에 야성을 쌓아 (Q)\'포악함\'으로 진입하는 타이밍을 노리세요. (Q)\'싹둑싹둑!\'의 중앙 범위에 계속 서 있으면 고정 피해를 입으니 주의하세요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 접근하여 그웬의 방어력을 낮추고 최대 야성 (E)\'올가미 투척\'으로 속박하세요. 그웬이 (R)\'바느질\'로 둔화를 걸며 저항하면 최대 야성 (W)\'전투의 포효\'로 군중 제어 효과를 해제하며 싸우세요. 수풀 근처에서 매복하여 순식간에 진입하는 구도를 만드세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 가세요. 마법 저항력을 챙기고 생명력 흡수로 전투를 지속하기 위해서예요.', spell: '점멸과 점화를 추천해요. 그웬은 (P)\'가위 난도질\'로 체력을 회복하니 점화로 회복을 줄여야 해요.' },
    '나르': { lv1: '나르는 (Q)\'부메랑 던지기\'로 멀리서 견제하며 둔화를 걸기 쉬워요. 수풀에 숨어 (P)\'보이지 않는 포식자\'의 도약 효과를 활용해 짧은 딜교환을 시도하세요. 나르의 (W)\'슝슝\' 추가 피해가 쌓이지 않게 평타를 너무 오래 맞지 않도록 조심해요.', lv3: '(E)\'올가미 투척\'의 야성 중첩을 쌓아 대상을 제자리에 묶는 것이 핵심이에요. 나르의 (E)\'폴짝\' 사용을 확인한 뒤 (Q)\'포악함\'으로 빠르게 진입해 딜을 넣으세요. 나르의 분노가 차올라 변신하기 전에 (W)\'전투의 포효\'로 체력을 관리하며 교환을 마무리해요.', lv6: '(R)\'사냥의 전율\'을 사용하여 위장 상태로 접근해 나르의 방어력을 감소시키며 공격하세요. 메가 나르가 (R)\'나르!\'로 벽에 부딪히게 하면 기절하니 벽 근처에서 싸우지 마세요. 나르가 변신하기 전후로 (E)\'올가미 투척\'을 맞혀 거리를 관리하며 킬각을 잡으세요.', item: '몰락한 왕의 검으로 생명력 흡수를 챙기며 전투를 지속하세요. 신발은 나르의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. (R)\'사냥의 전율\'로 진입할 때 점화로 부족한 피해를 보충하며 킬을 노려요.' },
    '나서스': { lv1: '나서스는 (Q)\'흡수의 일격\'으로 미니언을 먹으며 성장하려 하니 초반에 강하게 압박해야 해요. 수풀에서 (P)\'보이지 않는 포식자\'를 활용해 도약하며 (Q)\'포악함\'을 섞은 짧은 딜교환으로 나서스의 체력을 깎아두세요. 무리하게 맞딜을 하기보다 거리 조절을 하며 나서스가 미니언을 편하게 먹지 못하게 하는 것이 중요해요.', lv3: '나서스가 (W)\'쇠약\'을 사용해 속도를 늦추려 하면 (W)\'전투의 포효\'의 야성 효과로 군중 제어를 해제하며 대응하세요. (E)\'올가미 투척\'을 먼저 맞혀서 나서스의 움직임을 둔화시킨 뒤 (Q)\'포악함\'과 평타로 빠르게 피해를 입히고 빠져야 해요. (E)\'영혼의 불길\' 범위 안에서는 방어력이 낮아지니 주의하며 짧은 교전 위주로 진행하세요.', lv6: '(R)\'사냥의 전율\'을 사용해 나서스의 방어력을 낮추고 순간적인 피해로 킬을 노려보세요. 만약 나서스가 (R)\'사막의 분노\'를 켜서 체력과 방어력을 높였다면 무리하게 들어가지 말고 거리를 유지하며 버텨야 해요. 라인을 빠르게 밀어 넣어서 나서스가 (Q)\'흡수의 일격\' 중첩을 쌓기 어렵게 만들고 정글러의 개입을 유도하세요.', item: '몰락한 왕의 검을 첫 코어로 올려서 나서스의 높은 체력을 효과적으로 깎으세요. 신발은 나서스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 초반에 나서스의 체력 회복 효과를 감소시켜 킬각을 잡기 좋아요.' },
    '녹턴': { lv1: '1~2레벨에는 수풀의 (P)\'보이지 않는 포식자\'를 활용해 기습적인 도약을 시도하세요. 녹턴이 (Q)\'황혼의 인도자\'를 던져 이동 속도를 높이며 접근할 때는 거리를 벌리며 대응해요. 무리한 진입보다는 수풀 근처에서 짧은 딜교환을 유도하세요.', lv3: '(E)\'올가미 투척\'을 먼저 맞춰 둔화시킨 뒤 진입하여 (Q)\'포악함\'으로 빠르게 피해를 입히세요. 녹턴의 (W)\'어둠의 장막\'은 적의 다음 스킬을 한 번 막으니, 덜 중요한 스킬을 먼저 써서 그림자 장벽을 빼는 것이 중요해요. (E)\'말할 수 없는 공포\'에 연결되면 즉시 거리 밖으로 벗어나 공포에 걸리지 않도록 주의하세요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 접근하여 녹턴의 허점을 찌르세요. 상대가 (R)\'피해망상\'을 사용해 시야를 차단하고 돌격해 올 때는 당황하지 말고 수풀 근처에서 맞이하세요. 정글러가 개입하기 좋은 구도이므로 라인을 적절히 당겨서 유지하는 것이 좋아요.', item: '판금 장화와 몰락한 왕의 검을 선택해요. 녹턴의 기본 공격 피해를 판금 장화로 줄이고 몰락한 왕의 검의 생명력 흡수로 유지력을 높이기 위해서예요.', spell: '점멸과 점화. 녹턴의 (P)\'그림자 칼날\'로 인한 체력 회복을 억제하고 확실하게 마무리하기 위해서예요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\' 중첩이 쌓일수록 강해지니 1~2레벨에는 짧게 교환하고 빠지세요. (Q)\'학살\'의 도끼날에 맞으면 피해가 크니 도끼자루 부분에 맞도록 거리 조절을 하는 것이 좋아요. 수풀에서 (P)\'보이지 않는 포식자\'를 활용해 빠르게 (Q)\'포악함\'으로 피해를 주고 거리를 벌리세요.', lv3: '다리우스가 (E)\'포획\'을 사용해 끌어당기려 할 때 (E)\'올가미 투척\'으로 미리 둔화를 걸어 거리를 조절하세요. 야성이 쌓였을 때 (W)\'전투의 포효\'로 둔화를 해제하며 대응하세요. 다리우스의 (E)\'포획\'이 빠진 직후에 (Q)\'포악함\'을 섞어 빠르게 딜교환을 마치고 빠져야 해요.', lv6: '다리우스의 (R)\'녹서스의 단두대\'는 (P)\'과다출혈\' 중첩이 많을수록 치명적이니 중첩이 높을 때는 싸움을 피하세요. (R)\'사냥의 전율\'로 방어력을 깎고 위장 상태로 접근하여 다리우스가 (E)\'포획\'을 쓰기 전에 몰아붙이세요. 다리우스의 체력이 낮을 때 (R)\'사냥의 전율\'로 진입해 순식간에 킬을 노려보세요.', item: '굶주린 히드라를 첫 코어로 선택해 공격력과 생명력 흡수를 챙기며 전투를 지속하세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 다리우스의 (Q)\'학살\'로 인한 체력 회복을 억제하며 킬을 노리기 위해서예요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 직선으로 발사해 견제하니 미니언 뒤에 서서 피해를 줄이세요. 1~2레벨에는 수풀을 활용해 거리를 조절하며 (Q)\'포악함\' 강화 공격 기회를 엿보세요. 라이즈가 미니언을 먹으러 올 때 빠르게 붙어 체력을 깎는 것이 중요해요.', lv3: '(E)\'주문 전이\' 표식이 남은 상태에서 (W)\'룬 감옥\'에 맞으면 속박되니 주의하세요. 최대 야성 상태의 (E)\'올가미 투척\'을 먼저 맞히고 진입해 (Q)\'포악함\'으로 강하게 압박하세요. 만약 속박에 걸렸다면 최대 야성 (W)\'전투의 포효\'로 군중 제어 효과를 해제하며 대응하세요.', lv6: '(R)\'사냥의 전율\'로 위장해 접근하면 라이즈의 방어력을 깎고 기습적인 킬각을 잡을 수 있어요. 라이즈가 (R)\'공간 왜곡\'으로 차원문을 열면 상대 정글러가 함께 넘어올 수 있으니 라인을 너무 깊게 밀지 마세요. 최대 야성 (E)\'올가미 투척\'으로 라이즈를 속박한 뒤 (Q)\'포악함\'과 (W)\'전투의 포효\'를 쏟아부어 빠르게 처치하세요.', item: '맬모셔스의 아귀의 생명선 효과로 라이즈의 폭발적인 마법 피해를 견디고 역습하세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음으로 속박 지속 시간을 줄이세요.', spell: '점멸과 점화를 추천해요. 라이즈의 (W)\'룬 감옥\'에 속박되기 전에 빠르게 붙고, 점화의 마무리 피해로 체력이 낮은 라이즈를 처치하세요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'로 근접 거리에서 강하게 압박하며 미니언과 함께 공격해요. 수풀에서 (Q)\'포악함\'을 사용해 빠르게 치고 빠지는 식으로 피해를 누적시키세요. (E)\'전기 작살\'에 맞으면 마법 저항력이 줄어들어 더 아프니 거리 조절에 신경 쓰세요.', lv3: '럼블이 (W)\'고철 방패\'를 켜면 피해가 흡수되니 방패가 사라질 때까지 기다렸다가 진입하세요. 최대 야성 상태에서 (E)\'올가미 투척\'을 맞춰 럼블을 속박한 뒤 빠르게 접근해 피해를 입히세요. 럼블이 과열되어 스킬을 못 쓰는 틈을 타 (W)\'전투의 포효\'로 체력을 회복하며 싸우세요.', lv6: '(R)\'이퀄라이저 미사일\'의 화염 벽 위에서는 둔화와 피해가 심하니 빠르게 벗어나세요. (R)\'사냥의 전율\'로 위장해 진입한 뒤 럼블의 방어력을 깎고 순식간에 딜교환을 끝내세요. 럼블의 궁극기가 빠진 이후에 진입해야 정글러의 개입이나 반격에 대처하기 편해요.', item: '갈라진 하늘을 첫 코어로 가서 체력과 피해량을 챙기고 전투 유지력을 높이세요. 신발은 (E)\'전기 작살\'의 둔화 지속시간을 줄이고 마법 피해를 견디기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 럼블이 (W)\'고철 방패\'로 버티더라도 점화의 고정 피해를 더해 빠르게 처치하세요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 체력을 회복하며 압박하니 1~2레벨에는 거리를 유지하세요. 수풀에서 (P)\'보이지 않는 포식자\'로 도약한 뒤 (Q)\'포악함\'을 섞어 짧게 교환하고 빠지는 것이 좋아요. 레넥톤의 분노가 쌓여 강화된 스킬을 쓰기 전에 움직임을 조절하세요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 들어오며 (W)\'무자비한 포식자\'로 기절을 걸려 하니 (E)\'올가미 투척\'으로 거리를 조절하세요. (W)\'무자비한 포식자\'에 기절하면 스킬을 쓸 수 없으므로 맞기 전에 주의해야 해요. 야성이 쌓인 상태에서 (E)\'올가미 투척\'을 맞춰 대상을 묶으면 효과적으로 딜교환을 할 수 있어요.', lv6: '레넥톤이 (R)\'강신\'을 사용하면 추가 체력을 얻으니 정면 싸움보다는 수풀을 활용해 (R)\'사냥의 전율\'로 방어력을 낮추며 진입하세요. (R)\'사냥의 전율\'로 진입한 뒤 (E)\'올가미 투척\'으로 묶고 (Q)\'포악함\'을 연계해 빠르게 피해를 입히는 것이 좋아요. 레넥톤의 궁극기 지속시간이 끝나기를 기다리며 정글러의 개입을 유도하는 라인 관리를 하세요.', item: '굶주린 히드라를 첫 코어로 가서 강력한 피해를 입히세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 레넥톤의 (Q)\'양떼 도륙\' 회복량을 감소시키면 교전에서 더 잘 싸울 수 있어요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'를 사용해 돌진하며 (P)\'룬 검\' 피해를 입히는 구간이 강해요. 수풀에서 (P)\'보이지 않는 포식자\'로 먼저 도약하여 거리를 잡거나 리븐의 진입을 피하며 대응하세요.', lv3: '리븐의 (W)\'기 폭발\' 기절을 맞지 않도록 주의하며 (E)\'올가미 투척\'으로 먼저 견제하세요. 리븐이 (E)\'용맹\'으로 피해를 흡수하는 동안에는 공격을 아끼고, 보호막이 사라진 시점에 맞춰 딜교환을 시도하세요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 접근하여 리븐의 방어력을 깎으며 압박하세요. 리븐이 (R)\'추방자의 검\'을 켜고 바람 가르기를 사용하는 타이밍에는 무리하게 붙기보다 궁극기 효과를 조심하며 움직이세요.', item: '판금 장화와 몰락한 왕의 검을 가세요. 판금 장화로 리븐의 기본 공격 피해를 줄이고 몰락한 왕의 검으로 생명력 흡수를 챙겨요.', spell: '점멸과 점화를 추천해요. 리븐의 체력이 낮아졌을 때 점화로 마무리 피해를 입히면 좋아요.' },
    '리산드라': { lv1: '리산드라는 (Q)\'얼음 파편\'을 통해 멀리서 둔화를 걸며 견제하니 미니언 바로 뒤에 서지 않도록 조심하세요. 1~2레벨에는 수풀을 활용해 (P)\'보이지 않는 포식자\'로 도약하며 압박을 넣는 것이 좋아요. 상대의 견제를 피하며 야성을 쌓는 데 집중하세요.', lv3: '리산드라가 (W)\'서릿발\'로 발을 묶으려 하면 (E)\'올가미 투척\'을 맞춰서 반격하세요. 리산드라가 (E)\'얼음갈퀴 길\'을 사용해 거리를 벌리려 할 때 빠르게 접근해 딜교환을 이어가야 해요. 야성이 쌓인 상태에서 (Q)\'포악함\'을 섞어 공격하면 더 효과적이에요.', lv6: '(R)\'사냥의 전율\'로 진입해 방어력을 낮추고 몰아붙이되 리산드라가 자신에게 (R)\'얼음 무덤\'을 쓰면 무적이 풀릴 때까지 잠시 공격을 멈추세요. 나에게 (R)\'얼음 무덤\'을 쓰면 기절해서 스킬을 쓸 수 없으니, 리산드라의 궁극기가 남아 있을 때는 진입 각을 신중하게 잡으세요. 리산드라의 (E)\'얼음갈퀴 길\' 위치를 예측해 (E)\'올가미 투척\'을 맞히는 것이 중요해요.', item: '굶주린 히드라를 첫 코어로 선택해 생명력 흡수로 라인 유지력을 높이세요. 신발은 군중 제어 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. (R)\'얼음 무덤\'의 기절을 정화로 빠르게 풀고 전투를 이어가세요.' },
    '마스터이': { lv1: '1~2레벨에는 수풀을 활용한 (P)\'보이지 않는 포식자\'로 접근하여 (Q)\'포악함\'으로 빠르게 피해를 입히세요. 마스터 이의 (P)\'2연속 공격\'과 (E)\'우주류 검술\'은 평타가 매우 강하므로 수풀을 이용해 거리를 조절하며 싸워야 해요.', lv3: '마스터 이가 (W)\'명상\'을 쓰면 받는 피해량이 줄고 체력을 회복하므로 스킬을 아껴두며 대응하세요. 마스터 이의 (Q)\'일격 필살\'이 빠진 것을 확인하고 (E)\'올가미 투척\'을 맞춰서 둔화를 걸거나 야성이 높다면 속박을 활용하세요.', lv6: '마스터 이가 (R)\'최후의 전사\'를 켜면 둔화에 면역이 되므로 (E)\'올가미 투척\'의 둔화가 통하지 않아요. (R)\'사냥의 전율\'로 접근해 방어력을 깎고 야성을 모아 (E)\'올가미 투척\'의 속박을 맞춰야 킬을 낼 수 있어요.', item: '판금 장화와 몰락한 왕의 검을 가세요. 판금 장화는 마스터 이의 기본 공격 피해를 줄여주고 몰락한 왕의 검은 교전 시 생명력 흡수를 도와줘요.', spell: '점멸과 점화를 추천해요. 마스터 이의 (W)\'명상\' 체력 회복을 감소시켜야 해요.' },
    '마오카이': { lv1: '수풀에서 (P)\'보이지 않는 포식자\'를 활용해 먼저 도약하며 시작하세요. 마오카이가 (Q)\'덤불 주먹\'으로 밀어내며 둔화를 걸 수 있으니 거리를 조절하며 (Q)\'포악함\'을 맞히는 데 집중해요. 마오카이가 (P)\'마법 흡수\'로 체력을 회복하며 버티는 구간이니 무리한 교환은 피하세요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'으로 도약해 속박하는 동안은 대상을 지정할 수 없으니 주의하세요. 야성을 쌓아 (W)\'전투의 포효\'로 마오카이의 군중 제어 효과를 해제하며 딜교환을 해야 해요. (E)\'올가미 투척\'의 야성 효과인 속박을 맞히면 (Q)\'포악함\'과 함께 더 강하게 몰아붙일 수 있어요.', lv6: '(R)\'사냥의 전율\'로 도약해 마오카이의 방어력을 낮추고 폭발적인 피해를 입히세요. 마오카이가 (R)\'대자연의 마수\'로 벽을 세우면 그 경로에서 벗어나 속박을 피하는 것이 중요해요. 벽에 막혀 퇴로가 차단되지 않도록 조심하며 킬을 노리세요.', item: '첫 코어로 갈라진 하늘을 선택해 공격력과 체력을 확보하세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 마오카이가 (P)\'마법 흡수\'로 회복하는 것을 점화로 억제하며 킬을 노리세요.' },
    '말자하': { lv1: '말자하의 (P)\'공허 태세\'가 켜져 있으면 받는 피해가 크게 줄고 군중 제어에 면역이 되니, 피해를 한 번 입혀 효과를 먼저 끊으세요. (Q)\'공허의 부름\' 투사체가 날아오는 길목을 피해 거리를 조절하고, 수풀에서 (P)\'보이지 않는 포식자\'로 접근하세요. 1~2레벨에는 말자하의 사거리가 길지만 몸이 약하니 짧게 압박하세요.', lv3: '말자하가 (E)\'재앙의 환상\'을 사용하면 공허충들이 몰려오니 무리하게 딜교환을 이어가지 말고 빠져나오세요. (Q)\'공허의 부름\'이 발사될 때 경로를 잘 보고 피하며 침묵에 걸려 스킬을 못 쓰는 상황을 방지해야 해요. (E)\'올가미 투척\'으로 말자하를 둔화시키고 (Q)\'포악함\'을 섞어 짧고 강하게 공격하세요.', lv6: '(R)\'황천의 손아귀\'는 제압이라서 맞게 되면 아무것도 할 수 없으니 말자하의 위치를 항상 주시하세요. (R)\'사냥의 전율\'로 위장 상태에서 도약해 방어력을 깎고 (E)\'올가미 투척\'으로 연계하여 킬각을 노리세요. 말자하가 (W)\'공허의 무리\'를 소환해 라인을 밀면 수풀을 활용해 정글러의 개입을 유도하며 대응하세요.', item: '굶주린 히드라를 첫 코어로 선택해 라인 푸시력과 생명력 흡수를 챙기세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (R)\'황천의 손아귀\'는 정화로 풀 수 없는 제압 효과이니 점화로 확실하게 마무리하세요.' },
    '말파이트': { lv1: '말파이트는 (P)\'화강암 방패\'로 피해를 흡수하며 (Q)\'지진의 파편\'으로 이동 속도를 훔치는데, 이 스킬은 대상 지정 방식이라 미니언 뒤에 숨어도 피할 수 없어요. 수풀에서 대기하다가 방패가 사라진 타이밍에 (Q)\'포악함\'으로 도약해 짧게 교환하세요. 초반에는 방패가 재생성되기 전에 빠르게 공격하고 빠지는 것이 중요해요.', lv3: '야성을 최대로 쌓은 뒤 (E)\'올가미 투척\'으로 속박시키고 (Q)\'포악함\'으로 강한 피해를 입히세요. (E)\'지면 강타\'를 맞으면 공격 속도가 낮아져 평타 교환이 어려우니, 상대가 스킬을 쓴 직후에 진입하는 것이 좋아요. (W)\'천둥소리\' 강화 평타의 여진 피해를 최소화하며 짧게 치고 빠지세요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 돌진이라 맞으면 공중에 떠서 아무것도 할 수 없으니 주의하세요. 상대가 궁극기를 사용해 진입한 직후 (R)\'사냥의 전율\'로 도약해 방어력을 깎으며 공격하면 킬각을 잡기 편해요. 정글러가 근처에 있을 때는 말파이트의 돌진 거리 밖에서 대기하며 신중하게 움직이세요.', item: '몰락한 왕의 검을 첫 코어로 가서 높은 체력의 말파이트에게 효율적인 피해를 입히고 생명력 흡수로 유지력을 챙기세요. 신발은 마법 저항력과 강인함이 있는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점멸로 변수를 만들고 점화의 추가 피해로 체력이 높은 말파이트를 더 빠르게 처치하세요.' },
    '모데카이저': { lv1: '모데카이저의 (Q)\'말살\'은 범위 안의 모든 적에게 맞고 단일 대상에게 더 강해지니 혼자 맞는 위치는 피하세요. 수풀에서 (P)\'보이지 않는 포식자\'로 도약해 (Q)\'포악함\'으로 빠르게 공격하고, (P)\'암흑 탄생\' 오라가 켜지기 전에 물러나세요. 초반에는 짧은 교환을 반복하며 체력을 관리하는 것이 중요해요.', lv3: '(E)\'죽음의 손아귀\'에 끌려오면 (Q)\'말살\' 연계에 당하기 쉬우니 거리 조절을 철저히 하세요. 야성을 모아 (E)\'올가미 투척\'으로 먼저 속박시킨 뒤 (Q)\'포악함\'으로 빠르게 피해를 입히세요. (W)\'불멸\' 보호막이 생기기 전에 교환을 마치거나 (W)\'전투의 포효\'로 입은 피해를 회복하며 버티세요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 능력치를 뺏기고 빠져나올 수 없으니 사용 전에 최대한 체력을 깎아 두세요. (R)\'사냥의 전율\'을 켜고 위장 상태로 접근해 상대의 방어력을 낮춘 뒤 빠르게 진입하세요. 상대의 (E)\'죽음의 손아귀\'가 빠진 것을 확인하고 도약해 마무리하는 것이 안전해요.', item: '마법 저항력과 강인함이 있는 헤르메스의 발걸음을 신으세요. 첫 코어로 맬모셔스의 아귀를 가면 마법 저항력을 얻고, 체력이 낮아질 때 마법 피해를 막는 생명선 보호막을 챙길 수 있어요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과가 (W)\'불멸\'을 통한 체력 회복을 줄여 킬각을 잡기 좋아요.' },
    '문도박사': { lv1: '문도 박사는 (Q)\'오염된 뼈톱\'으로 체력 비례 피해를 주고 둔화를 걸어요. 이 스킬은 처음 맞는 대상에게 적중하니 미니언 뒤에서 피하고, (P)\'보이지 않는 포식자\'로 도약해 짧게 공격하며 견제하세요. 통을 주워 체력을 회복하기 전에 수풀을 활용해 빠르게 빠지세요.', lv3: '(W)\'심장 전기 충격\'을 켠 문도 박사와는 길게 싸우지 말고 피해를 저장하기 전에 빠르게 교환하세요. (E)\'올가미 투척\'의 속박 효과는 (P)\'가고 싶은 데로 간다\'로 한 번 무시하니, 패시브를 뺀 뒤에 다시 묶어야 해요. 야성을 모아 (Q)\'포악함\'으로 강하게 때리고 빠르게 거리를 벌리세요.', lv6: '(R)\'사냥의 전율\'로 방어력을 깎으며 도약해 순간적으로 큰 피해를 입히세요. 하지만 (R)\'최대 투여량\'을 사용하면 체력을 크게 회복하니, 궁극기가 빠진 것을 확인하고 진입하는 것이 좋아요. 문도 박사가 회복 스킬을 쓴 뒤에는 무리하게 추격하지 말고 라인을 관리하며 정글러를 부르세요.', item: '몰락한 왕의 검을 첫 코어로 가서 문도 박사의 많은 체력을 빠르게 깎으세요. 신발은 (Q)\'오염된 뼈톱\'과 (W)\'심장 전기 충격\'의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 문도 박사는 (R)\'최대 투여량\'과 패시브로 체력 회복량이 매우 많아서 점화의 치유 감소가 필수적이에요.' },
    '바루스': { lv1: '바루스의 (Q)\'꿰뚫는 화살\'은 적을 관통하는 투사체라 미니언 뒤에 숨어도 막히지 않으니 조준하는 방향에서 비켜서세요. 화살을 쏜 직후에 (P)\'보이지 않는 포식자\'로 도약해 붙은 뒤 (Q)\'포악함\'으로 빠르게 공격하고 빠지세요. 계속 거리만 벌리면 체력이 깎이므로 짧고 강하게 교전하세요.', lv3: '(E)\'퍼붓는 화살\'의 오염된 지면은 이동 속도를 늦추고 회복을 방해하니 빠르게 벗어나세요. 야성을 모아 (E)\'올가미 투척\'으로 바루스를 속박시킨 뒤 (W)\'전투의 포효\'로 피해를 입히고 체력을 회복하세요. 바루스가 (W)\'역병 화살\'을 사용해 강화된 화살을 조준할 때 빠르게 진입해 흐름을 끊으세요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 접근하고 방어력을 깎아 짧은 시간에 체력을 빼세요. 다만 진입 시 (R)\'부패의 사슬\'에 속박되면 집중 공격을 받으니, 상대의 궁극기가 빠진 것을 확인하고 도약하세요. 정글러와 함께 바루스를 압박하며 라인을 밀어붙이세요.', item: '판금 장화와 몰락한 왕의 검을 추천해요. 판금 장화는 기본 공격 피해를 줄여주고 몰락한 왕의 검은 생명력 흡수로 교전 유지력을 높여줘요.', spell: '점멸과 점화를 추천해요. 점멸로 진입 변수를 만들고 점화로 바루스를 확실하게 마무리하세요.' },
    '베인': { lv1: '베인은 (W)\'은화살\'로 같은 대상에게 세 번째 타격마다 고정 피해를 입히니 평타를 길게 맞지 마세요. 1~2레벨에는 수풀에 숨어 (P)\'보이지 않는 포식자\'로 접근하며 (Q)\'포악함\'을 섞은 짧은 공격으로 베인을 압박하세요.', lv3: '베인이 (E)\'선고\'로 밀쳐서 벽에 부딪히면 기절하므로 지형 근처에서는 싸우지 마세요. 베인이 (Q)\'구르기\'로 거리를 벌리기 전에 (E)\'올가미 투척\'을 맞혀서 움직임을 제어하는 것이 중요해요. 야성을 최대로 쌓은 뒤 (E)\'올가미 투척\'으로 상대를 묶으면 연속적인 공격이 가능해요.', lv6: '(R)\'사냥의 전율\'을 사용해 방어력을 낮추고 도약하여 베인을 빠르게 제압하세요. 베인이 (R)\'결전의 시간\'을 사용하면 (Q)\'구르기\'를 쓸 때 투명해지니 위치를 잘 파악해야 해요. 라인을 밀어 넣은 뒤 정글러와 함께 베인을 노리세요.', item: '베인의 기본 공격 피해를 줄이기 위해 판금 장화를 신으세요. 몰락한 왕의 검을 첫 코어로 선택해 생명력 흡수로 라인전을 견뎌내세요.', spell: '점멸과 점화를 추천해요. 베인이 (Q)\'구르기\'로 거리를 벌리며 도망칠 때 점멸로 따라붙고 점화로 마무리하세요.' },
    '볼리베어': { lv1: '볼리베어가 (Q)\'번개 강타\'로 빠르게 달려와 기절을 걸려고 하니 수풀을 이용해 거리를 조절하세요. (E)\'올가미 투척\'을 먼저 맞춰 둔화를 걸어 접근을 늦추고 야성을 쌓는 것이 중요해요. 볼리베어의 (P)\'무자비한 폭풍\' 때문에 붙어서 오래 싸우면 피해가 커지니 짧게 치고 빠지세요.', lv3: '볼리베어가 (E)\'천공 분열\'로 번개를 내리면 그 범위 안에서 보호막을 얻으니 범위를 피해 싸우세요. (W)\'광란의 상처\' 표식이 남았을 때 계속 맞붙으면 볼리베어가 체력을 회복하니 주의하세요. (Q)\'번개 강타\'에 기절하면 스킬을 쓸 수 없으니 기절이 걸리기 전에 (E)\'올가미 투척\'으로 둔화를 걸어 접근을 늦추세요.', lv6: '(R)\'폭풍을 부르는 자\'로 포탑을 비활성화하며 들어올 수 있으니 체력이 낮을 때 포탑만 믿고 있으면 위험해요. (R)\'사냥의 전율\'로 위장해 접근하여 볼리베어의 방어력을 깎고 강력한 한 번의 공격을 넣으세요. 상대가 궁극기로 도약한 직후의 틈을 노려 (E)\'올가미 투척\'으로 묶고 빠르게 피해를 입히세요.', item: '몰락한 왕의 검을 가서 체력이 높은 볼리베어에게 효율적인 피해를 입히세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'광란의 상처\'의 회복 효과를 억제하기 위해 점화가 필요해요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 체력을 회복하며 견제해요. 수풀을 활용해 (P)\'보이지 않는 포식자\'로 도약하며 짧게 딜교환을 시도하세요. (Q)\'수혈\'은 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없으니 거리를 조절해요.', lv3: '블라디미르가 (E)\'선혈의 파도\'를 쓰면 미니언 뒤로 숨어 피해를 줄이세요. (W)\'피의 웅덩이\'를 사용해 공격을 피하면 (E)\'올가미 투척\'으로 둔화를 걸어도 무의미하니 웅덩이가 끝난 후 진입해요. (E)\'올가미 투척\'으로 먼저 둔화를 걸며 거리를 좁히는 것이 좋아요.', lv6: '(R)\'사냥의 전율\'을 사용해 방어력을 낮추며 진입하여 킬각을 잡으세요. 블라디미르가 (R)\'혈사병\'을 사용해 감염시키면 받는 피해가 커지니 조심해야 해요. (W)\'피의 웅덩이\'가 빠진 상태에서 정글러를 호출해 공격하세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 추천해요. 마법 저항력을 챙겨 피해를 견디고 몰락한 왕의 검으로 전투 지속력을 높여요.', spell: '점멸과 점화를 추천해요. 점화로 블라디미르의 (Q)\'수혈\' 회복 효과를 줄여야 해요.' },
    '뽀삐': { lv1: '수풀을 활용해 (P)\'보이지 않는 포식자\'로 접근하여 뽀삐가 (P)\'강철의 외교관\'으로 보호막을 얻기 전에 (Q)\'포악함\'을 사용하세요. 뽀삐가 (Q)\'망치 강타\'로 만든 둔화 지대를 밟지 않도록 주의하며 거리 조절을 하세요. 초반에는 짧게 치고 빠지는 방식으로 대응하세요.', lv3: '뽀삐가 (W)\'굳건한 태세\'를 사용하면 (P)\'보이지 않는 포식자\'를 통한 도약이 막히고 이동 스킬을 못 쓰게 되니 주의하세요. (E)\'올가미 투척\'으로 둔화를 건 뒤 딜교환을 하되, 뽀삐가 (E)\'용감한 돌진\'으로 벽에 밀어내지 못하도록 벽 근처에서 싸우지 마세요. (W)\'굳건한 태세\'가 끝난 뒤에 진입하는 것이 좋아요.', lv6: '(R)\'사냥의 전율\'로 위장 상태가 되어 접근한 뒤 뽀삐의 방어력을 깎으며 (E)\'올가미 투척\'을 맞혀 보세요. 뽀삐가 (R)\'수호자의 심판\'을 사용해 멀리 날리려 한다면 집중하는 동안 빠르게 범위를 벗어나야 해요. (W)\'굳건한 태세\'를 빼놓은 상태에서 (R)\'사냥의 전율\'로 도약하면 킬을 노리기 좋아요.', item: '코어 아이템으로 칠흑의 양날 도끼를 가고 신발은 판금 장화를 선택하세요. 칠흑의 양날 도끼는 깎아내기 효과로 뽀삐를 압박하기 좋고, 판금 장화는 뽀삐의 기본 공격 피해를 줄여줘요.', spell: '점멸과 점화를 추천해요. 점화로 뽀삐의 체력을 낮추어 킬을 만들어내기 좋아요.' },
    '사이온': { lv1: '사이온의 (E)\'학살자의 포효\'는 미니언을 밀어내며 뒤의 적까지 맞히니 미니언과 일직선으로 서지 마세요. (Q)\'대량 학살 강타\'를 충전하는 동작이 보이면 옆으로 비켜서 헛치게 유도하세요. 틈이 보일 때 (Q)\'포악함\'으로 짧게 딜교환을 하고 빠르게 빠지세요.', lv3: '최대 야성 상태의 (E)\'올가미 투척\'으로 사이온을 속박시킨 뒤 (Q)\'포악함\'으로 몰아치세요. 사이온이 (W)\'영혼의 용광로\' 보호막을 켜면 피해가 흡수되니 보호막이 터지거나 사라진 뒤에 공격하세요. (Q)\'대량 학살 강타\'의 기절 범위에서 벗어난 뒤 (W)\'전투의 포효\'로 체력을 회복하며 버티세요.', lv6: '(R)\'사냥의 전율\'로 도약해 방어력을 깎은 뒤 강력한 피해를 입히세요. 사이온이 (R)\'멈출 수 없는 맹공\'으로 돌진해 오면 저지 불가 상태이므로 옆으로 비켜나 공중으로 띄워지는 것을 피하세요. (P)\'영광스러운 죽음\'으로 되살아난 사이온은 공격 속도가 매우 빠르니 무리하게 붙지 말고 거리를 벌리세요.', item: '체력이 높은 사이온을 잡기 위해 몰락한 왕의 검을 첫 코어로 가세요. 신발은 (Q)\'대량 학살 강타\'의 기절 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 사이온이 라인을 강하게 밀어내는 편이라 순간이동으로 빠르게 복귀하는 것이 중요해요.' },
    '사일러스': { lv1: '수풀을 적극적으로 활용하여 (P)\'보이지 않는 포식자\'로 사일러스에게 접근하며 압박하세요. 사일러스가 (Q)\'사슬 후려치기\'를 사용하면 사슬이 교차하는 지점을 피하면서 거리를 조절해야 해요. 1~2레벨 구간에서는 사일러스의 패시브가 발동되지 않도록 주의하며 딜교환을 하세요.', lv3: '사일러스가 (E)\'도주 / 억압\'의 사슬을 던지려 할 때 옆으로 움직여서 피한 뒤 (E)\'올가미 투척\'으로 묶어주세요. 사슬에 맞으면 공중으로 띄워져 스킬을 쓸 수 없으니 던지는 방향을 잘 보세요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복하려 하면 (Q)\'포악함\'을 섞어 빠르게 피해를 입히세요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 진입하여 사일러스의 방어력을 깎고 폭발적인 피해를 입히세요. 사일러스가 (R)\'강탈\'을 통해 내 궁극기를 가져가 도약할 수 있으니 사일러스의 위치를 항상 확인하며 거리 조절을 해야 해요. 정글러와 함께 싸울 때는 (E)\'올가미 투척\'으로 사일러스의 이동을 방해하며 적을 고립시키세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 전투 지속력을 높이세요. 신발은 사일러스의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 사일러스의 (W)\'국왕시해자\' 회복을 억제하세요.' },
    '세주아니': { lv1: '수풀을 통해 (P)\'보이지 않는 포식자\'로 진입하며 (Q)\'포악함\'으로 짧게 피해를 입히고 빠지세요. 세주아니의 (W)\'혹한의 서릿발\'은 둔화를 거니 맞은 뒤에는 무리하게 쫓지 말고 거리를 조절하세요. 수풀 근처에서 파밍하며 기회를 노리세요.', lv3: '(E)\'올가미 투척\'을 먼저 맞혀 이동을 제한한 뒤 (Q)\'포악함\'으로 공격하세요. 상대의 (Q)\'혹한의 맹습\'에 맞아 공중으로 뜨면 스킬을 쓸 수 없고 (W)\'전투의 포효\'로도 풀 수 없으니 돌진 방향에서 비켜서세요. (E)\'만년 서리\' 기절이 들어오기 전에 빠르게 딜교환을 마치고 빠져야 해요.', lv6: '(R)\'사냥의 전율\'로 진입해 방어력을 낮추고 빠르게 공격하여 킬각을 잡으세요. 세주아니의 (R)\'빙하 감옥\'에 기절하면 위험하니 상대의 궁극기 사용 여부를 확인하고 진입하는 것이 중요해요. 정글러와 함께 수풀에서 기습하여 빠르게 제압하는 방식으로 라인을 압박하세요.', item: '헤르메스의 발걸음과 칠흑의 양날 도끼를 가요. 강인함으로 기절과 둔화 지속시간을 줄이고, 칠흑의 양날 도끼의 깎아내기로 방어력을 깎아 피해를 늘리기 위해서예요.', spell: '점멸과 점화. 순간적인 이동으로 진입 각을 만들고 강력한 피해로 킬을 내기 위해서예요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'으로 빠르게 접근해 강력한 평타를 날리니 거리를 두고 대응하세요. 수풀에서 (P)\'보이지 않는 포식자\'로 짧게 진입해 (E)\'올가미 투척\'으로 둔화를 걸고 빠르게 빠지세요. (P)\'투기장의 투지\' 회복 때문에 길게 싸우면 손해이니 짧은 딜교환을 반복하세요.', lv3: '세트의 (E)\'안면 강타\'는 양옆에 적이 있어야 기절시키니 세트를 사이에 두고 내 미니언과 반대편에 서지 않도록 주의하세요. 세트가 피해를 많이 입어 (W)\'강펀치\'의 투지가 가득 찼을 때는 정면에서 붙지 말고 거리를 벌리세요. 야성을 쌓은 뒤 (W)\'전투의 포효\'로 군중 제어를 해제하며 (Q)\'포악함\'으로 빠르게 피해를 입히고 빠지세요.', lv6: '(R)\'사냥의 전율\'로 위장 진입해 세트의 방어력을 깎으며 강력한 일격을 날리세요. 세트의 (R)\'대미 장식\'은 제압 효과라 잡히면 아무것도 할 수 없으니 세트의 거리 조절에 유의하세요. (R)\'대미 장식\'이 빠진 것을 확인한 뒤에 진입하면 훨씬 안전하게 적을 처치할 수 있어요.', item: '굶주린 히드라와 판금 장화를 추천해요. 굶주린 히드라의 생명력 흡수로 유지력을 높이고 판금 장화로 세트의 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. 세트의 (P)\'투기장의 투지\'를 통한 체력 회복을 점화의 치유 감소로 억제하세요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'을 사용해 최대 체력 비례 피해를 입히며 (P)\'기 보호막\'을 얻으니 무리하게 딜교하지 마세요. 1~2레벨에는 수풀을 활용해 (Q)\'포악함\'을 섞은 도약 공격으로 쉔의 보호막이 생기기 전에 짧게 찌르세요. (Q)\'황혼 강습\'의 기의 검이 지나가는 위치를 잘 보고 피해가 들어오지 않게 거리를 조절해요.', lv3: '쉔이 (E)\'그림자 돌진\'을 사용하여 도발을 먼저 쓰도록 유도하고, 도발이 빠진 뒤에 (E)\'올가미 투척\'을 맞히며 딜교를 시작하세요. 쉔이 (W)\'의지의 결계\'를 펼치면 평타가 차단되므로 결계가 사라진 뒤에 야성을 활용해 공격하세요. (E)\'올가미 투척\'이 속박이 되었을 때 확실하게 딜을 넣으세요.', lv6: '쉔이 (R)\'단결된 의지\'를 사용하여 다른 라인으로 이동하면 빠르게 라인을 밀어 압박하세요. (R)\'사냥의 전율\'로 위장 상태에서 도약해 쉔의 방어력을 낮추고 (Q)\'포악함\'을 활용해 빠르게 처치하세요. 쉔이 (E)\'그림자 돌진\'을 사용해 도발을 걸기 전에 먼저 공격을 성공시키는 것이 중요해요.', item: '굶주린 히드라를 첫 코어로 가서 강력한 공격력과 생명력 흡수를 챙기세요. 신발은 쉔의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 쉔의 (P)\'기 보호막\'이 사라진 순간에 점화를 사용하여 킬을 노리세요.' },
    '쉬바나': { lv1: '1~2레벨에는 쉬바나의 (Q)\'잉걸불 일격\'을 통한 견제에 주의하며 수풀 근처에서 대기해요. (E)\'올가미 투척\'을 활용해 거리를 조절하며 상대의 움직임을 확인하세요. 수풀을 이용해 패시브 도약을 준비하며 쉬바나가 미니언을 챙기는 타이밍을 노려요.', lv3: '스킬이 모두 모이면 (E)\'올가미 투척\'으로 상대를 묶고 (Q)\'포악함\'을 사용하여 압박해요. 쉬바나의 (W)\'지옥불 방패\' 보호막이 사라진 시점에 (Q)\'포악함\'을 맞춰 딜교환을 시도해요. 상대의 (E)\'용암 분출\'을 피하면서 야성 중첩을 쌓는 것이 중요해요.', lv6: '(R)\'사냥의 전율\'로 상대의 방어력을 낮추며 빠르게 접근해 피해를 입혀요. 쉬바나가 (R)\'용의 강림\'을 사용하여 용으로 변신하면 맞서지 말고 거리를 벌리세요. (W)\'전투의 포효\'로 체력을 회복하며 정글러의 지원을 받아 킬을 노려요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 선택해요. 마법 저항력을 높이고 생명력 흡수로 유지력을 높여요.', spell: '점멸과 점화. 킬을 노리고 상대의 체력 회복 효과를 감소시켜요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 견제하며 (P)\'굶주린 새떼\'로 체력을 회복해요. 수풀에서 (P)\'보이지 않는 포식자\' 도약으로 빠르게 접근해 (Q)\'포악함\'을 섞어 짧게 딜교환하세요. 초반에 체력 차이를 벌려야 스웨인이 나중에 단단해지는 것을 막을 수 있어요.', lv3: '(E)\'속박명령\'의 파동이 돌아오며 속박을 거니 옆으로 피해 보세요. 최대 야성 상태의 (W)\'전투의 포효\'를 사용하면 (E)\'속박명령\'에 걸려도 즉시 해제하고 싸울 수 있어요. (E)\'올가미 투척\'으로 먼저 상대를 묶어둔 뒤 빠르게 공격하고 빠지세요.', lv6: '스웨인이 (R)\'악의 승천\'을 켜면 주변 생명력을 흡수하니 너무 오래 붙어 있지 마세요. (R)\'사냥의 전율\'로 위장해 접근한 뒤, 변신이 풀린 타이밍에 진입해 빠르게 처치하세요. 정글러가 올 때 (E)\'올가미 투척\'으로 묶어주면 함께 정리하기 편해요.', item: '몰락한 왕의 검을 첫 코어로 가서 스웨인의 높은 체력을 깎으세요. 신발은 (E)\'속박명령\'의 속박 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 스웨인은 (R)\'악의 승천\'과 (P)\'굶주린 새떼\'로 계속 회복하니 점화로 회복량을 줄여야 해요.' },
    '스카너': { lv1: '1~2레벨에는 (Q)\'부서진 대지/지반 돌출\'의 물리 피해와 둔화를 조심하며 거리를 유지하세요. 수풀을 활용해 (P)\'보이지 않는 포식자\'로 이득을 챙기며 스카너의 움직임을 살피는 것이 좋아요.', lv3: '야성을 모아 (E)\'올가미 투척\'으로 상대를 둔화시키거나 묶으며 딜교환을 시작하세요. 스카너의 (E)\'이쉬탈의 격돌\'에 걸려 벽에 부딪히지 않도록 주의하며 (W)\'전투의 포효\'의 야성 효과로 군중 제어를 해제해요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 진입하여 방어력을 낮추고 공격하세요. 스카너의 (R)\'꿰뚫기\'에 제압당하면 아무것도 할 수 없으니 주의가 필요해요. 상대 궁극기가 빠지면 정글러를 불러 함께 압박하세요.', item: '판금 장화와 굶주린 히드라를 추천해요. 판금 장화는 기본 공격 피해를 줄여주고, 굶주린 히드라는 공격력과 생명력 흡수를 제공해요.', spell: '점멸과 점화. 점멸로 거리를 좁히고 점화로 마무리 피해를 입혀요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'로 독구름을 남겨 지속 피해를 주니 구름 위에서는 싸우지 마세요. 수풀에서 (P)\'보이지 않는 포식자\'를 활용해 도약한 뒤 (Q)\'포악함\'으로 짧은 딜교환을 시도하세요. 신지드가 (P)\'독성 급류\'로 이동 속도를 높여 다가오면 거리를 조절하며 대응하세요.', lv3: '신지드가 (W)\'초강력 접착제\'를 사용하면 이동 스킬을 쓸 수 없으니 바닥을 잘 확인하고 진입하세요. (E)\'올가미 투척\'으로 신지드를 먼저 둔화시킨 뒤 (Q)\'포악함\'으로 딜교환을 시도하세요. 신지드가 (E)\'던져넘기기\'로 던질 때는 에어본을 피할 수 없으니 던져진 후의 위치를 미리 생각하세요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 접근하면 신지드의 방어력을 낮추어 킬을 노리기 쉬워요. 신지드가 (R)\'광기의 물약\'을 마셔 방어력과 체력 재생력을 높이면 정면 승부를 피하고 (W)\'초강력 접착제\'가 빠진 타이밍을 노리세요. 신지드가 라인을 빠르게 밀면 수풀 시야를 확보하며 정글러와 함께 대응하세요.', item: '첫 코어로 굶주린 히드라를 구매하여 공격력과 생명력 흡수를 챙기세요. 신발은 신지드의 마법 피해를 견디기 위해 헤르메스의 발걸음을 신으세요.', spell: '점멸과 점화를 추천해요. 점화로 신지드의 체력을 빠르게 깎고, 점멸은 (W)\'초강력 접착제\' 범위 밖에서 진입 거리를 좁힐 때 쓰세요.' },
    '신짜오': { lv1: '신짜오가 (Q)\'삼조격\'의 마지막 공격으로 공중으로 띄우기 전에 거리를 조절하며 (Q)\'포악함\'으로 견제해요. 초반에는 무리하게 진입하기보다 수풀을 활용해 상대의 움직임을 확인하며 피해를 줄여요.', lv3: '신짜오가 (E)\'무쌍돌격\'으로 들어올 때 (E)\'올가미 투척\'을 맞춰서 이동을 제한하는 것이 중요해요. (W)\'풍전참뢰\'의 둔화에 걸리지 않도록 주의하면서 야성을 쌓아 강화된 (Q)\'포악함\'으로 빠르게 딜교환을 마쳐요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 접근하여 방어력을 낮추고 몰아붙여요. 신짜오가 (R)\'현월수호\'를 쓰면 도전 받지 않은 적은 뒤로 밀려나고 창이 닿는 거리 밖의 공격은 피해를 주지 못하니, 궁극기가 빠진 뒤에 진입하세요.', item: '판금 장화와 굶주린 히드라를 추천해요. 판금 장화로 신짜오의 기본 공격 피해를 줄이고 굶주린 히드라의 생명력 흡수로 유지력을 높여요.', spell: '점멸과 점화. 킬각을 잡거나 도망가는 적을 처단하기 좋아요.' },
    '아이번': { lv1: '1~2레벨에는 아이번의 (Q)\'덩굴뿌리\'에 맞지 않도록 주의하며 미니언 뒤에서 거리를 조절하세요. 아이번이 (W)\'수풀 가꾸기\'로 생성한 수풀을 활용해 (P)\'보이지 않는 포식자\'로 도약할 준비를 하며 기회를 엿보세요.', lv3: '아이번이 (E)\'보호의 씨앗\'을 사용하여 보호막을 형성하기 전에 (E)\'올가미 투척\'으로 먼저 접근하세요. (Q)\'포악함\'을 활용한 빠른 공격으로 아이번의 보호막이 폭발하기 전 최대한의 피해를 입히는 것이 중요해요.', lv6: '(R)\'사냥의 전율\'을 통해 위장 상태로 접근하여 아이번의 방어력을 깎으며 공격하세요. (R)\'데이지!\'의 충격파에 맞으면 공중으로 떠올라 스킬을 쓸 수 없고 (W)\'전투의 포효\'로도 풀 수 없으니, 데이지가 같은 대상을 연속으로 공격하는 동안 거리를 조절하세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 추천해요. 아이번의 마법 피해에 대응하고 (Q)\'덩굴뿌리\'의 속박 지속시간을 줄이기 위해서예요. 몰락한 왕의 검으로 전투 유지력을 높이세요.', spell: '점멸과 점화. 점멸로 (Q)\'덩굴뿌리\'를 피하거나 거리를 좁히고 점화로 강력한 피해를 입히기 위해서예요. 아이번의 보호막을 뚫고 빠르게 처치하세요.' },
    '아지르': { lv1: '수풀을 적극적으로 활용하여 (P)\'보이지 않는 포식자\'를 준비하며 거리를 조절하세요. 아지르가 (Q)\'사막의 맹습\'으로 견제할 때 무리하게 맞서지 말고 수풀 안에서 체력을 관리하며 다음 기회를 기다려요.', lv3: '아지르의 (E)\'신기루\' 사용을 확인한 뒤 (E)\'올가미 투척\'을 명중시켜 움직임을 둔화시키세요. 이후 야성을 활용한 (Q)\'포악함\' 공격으로 아지르에게 강력한 피해를 입히며 딜교환을 해요.', lv6: '(R)\'사냥의 전율\'로 위장 상태가 되어 접근한 뒤 아지르의 (R)\'황제의 진영\'에 밀려나지 않도록 주의하세요. 아지르의 체력이 낮을 때 (E)\'올가미 투척\'으로 속박을 걸어 확실하게 처치하세요.', item: '헤르메스의 발걸음과 굶주린 히드라를 가세요. 아지르의 마법 피해에 저항하며 전투를 지속하기 위해 선택해요.', spell: '점멸과 점화. 점화로 마무리 피해를 입혀요.' },
    '아칼리': { lv1: '아칼리가 (Q)\'오연투척검\'으로 둔화를 걸며 견제하니 수풀 근처에서 거리 조절을 하세요. 수풀에서 (Q)\'포악함\'을 켠 도약으로 짧게 딜교환을 하고 빠르게 빠져나와야 해요. (P)\'암살자의 표식\' 원 경계 근처에서 강화 평타를 맞지 않도록 주의하세요.', lv3: '야성을 최대로 쌓은 (E)\'올가미 투척\'으로 아칼리를 속박해 돌진 경로를 차단하세요. 아칼리가 (W)\'황혼의 장막\'을 쓰면 대상 지정이 안 되니, (W)\'전투의 포효\' 범위 피해로 대응하며 연막이 걷히길 기다리세요. (E)\'표창곡예\' 표식이 남았을 때 무리하게 진입하면 다시 돌진당할 수 있으니 주의하세요.', lv6: '(R)\'사냥의 전율\'로 위장해 접근한 뒤 방어력을 깎고 빠르게 공격하세요. 아칼리가 (R)\'무결처형\'으로 거리 조절을 하며 도망가면 무리하게 쫓지 말고 정글의 도움을 받으세요. 체력이 낮은 상태에서는 (R)\'무결처형\'의 두 번째 돌진에 피해를 크게 입을 수 있으니 항상 체력을 관리하세요.', item: '맬모셔스의 아귀를 가서 아칼리의 마법 피해를 생명선 보호막으로 버티세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 체력이 낮은 아칼리를 확실하게 마무리하세요.' },
    '아크샨': { lv1: '수풀을 활용해 (P)\'보이지 않는 포식자\'의 도약을 준비하며 (Q)\'복수의 부메랑\' 견제를 피하세요. 상대의 사거리가 길기 때문에 무리하게 맞서기보다 거리 조절을 하며 체력을 관리하는 것이 좋아요.', lv3: '야성이 쌓였을 때 (E)\'올가미 투척\'을 먼저 맞혀서 상대가 (E)\'영웅의 비상\'으로 도망가지 못하게 하세요. (Q)\'포악함\'으로 빠르게 진입해 피해를 입히고 (W)\'전투의 포효\'로 체력을 회복하며 딜교환을 이어가세요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 접근하여 방어력을 깎고 기습적인 공격을 시도하세요. 체력이 낮을 때는 상대의 (R)\'인과응보\'에 큰 피해를 입을 수 있으니 주의하며 정글러를 호출해 압박하세요.', item: '판금 장화와 굶주린 히드라를 추천해요. 판금 장화는 기본 공격으로 받는 피해량을 줄여주고 굶주린 히드라는 공격력과 생명력 흡수로 전투 지속력을 높여줘요.', spell: '점멸과 점화예요. 순간적인 진입과 부족한 마무리 피해를 보완하기 위해 선택하세요.' },
    '아트록스': { lv1: '수풀을 활용해 (P)\'보이지 않는 포식자\'로 도약하며 압박하세요. 아트록스의 (Q)\'다르킨의 검\' 끝자락에 맞으면 공중으로 띄워지니 범위를 잘 피하며 (Q)\'포악함\'으로 짧게 딜교환을 해요. (P)\'사신 태세\'가 켜진 평타는 체력을 회복하니 맞대결을 피하세요.', lv3: '아트록스의 (W)\'지옥사슬\'에 맞았다면 중앙으로 끌려가지 않게 빠르게 원 밖으로 벗어나세요. (E)\'올가미 투척\'으로 먼저 둔화를 걸고 (W)\'전투의 포효\'를 사용해 입은 피해를 회복하며 버티세요. 아트록스가 (E)\'파멸의 돌진\'으로 거리를 조절할 때 빈틈을 노려야 해요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태에서 진입하며 대상의 방어력을 깎고 폭발적인 피해를 입히세요. 아트록스가 (R)\'세계의 종결자\'를 사용하여 공격력과 체력 회복량이 늘어난 상태라면 정면 대결을 피하세요. 궁극기 효과가 끝난 뒤 (E)\'올가미 투척\'으로 대상을 묶고 마무리하세요.', item: '굶주린 히드라와 헤르메스의 발걸음을 가세요. 마법 저항력으로 (P)\'사신 태세\'의 피해를 견디고 강인함으로 (W)\'지옥사슬\'의 둔화를 줄여줘요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'사신 태세\'의 회복을 억제하세요.' },
    '암베사': { lv1: '암베사는 (P)\'용사냥개의 발걸음\'으로 스킬 사용 후 짧게 돌진하며 강한 평타를 날려요. (P)\'보이지 않는 포식자\'로 수풀에서 도약해 기습하되, (Q)\'교활한 휩쓸기\'의 반원 범위 끝에 걸리지 않게 주의하세요. 첫 웨이브에서는 무리하게 붙기보다 야성을 쌓으며 짧은 딜교환만 하세요.', lv3: '(E)\'올가미 투척\'을 최대 야성 상태로 맞춰 암베사를 속박하고 (Q)\'포악함\'으로 빠르게 피해를 입히세요. 암베사가 (W)\'배척\'의 보호막을 켜고 준비할 때는 딜을 멈추고 기다렸다가 보호막이 끝난 뒤에 진입하세요. (E)\'찢어 가르기\'의 둔화에 걸리면 거리를 벌리기 어려우니 (W)\'전투의 포효\'로 빠르게 상황을 정리하며 대응하세요.', lv6: '(R)\'사냥의 전율\'로 위장해 진입하여 암베사의 방어력을 깎고 순식간에 폭딜을 넣으세요. 암베사의 (R)\'공개 처형\'은 가장 멀리 있는 적을 제압하니, 교전 시 적과 너무 멀리 떨어져 있지 않도록 위치를 잡으세요. 제압에 걸리면 어떤 스킬도 쓸 수 없으므로 (R)\'사냥의 전율\' 도약 전에 암베사의 궁극기 사용 여부를 확인하세요.', item: '굶주린 히드라를 첫 코어로 선택해 공격력과 생명력 흡수로 유지력을 챙기세요. 신발은 암베사의 강한 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 암베사의 높은 기동성으로 빠져나가기 전에 점화의 강력한 피해로 확실하게 마무리하세요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'로 멀리서 견제하며 접근을 방해해요. 구체가 날아오는 길을 보고 옆으로 비켜서며 미니언을 챙기고, 수풀 속에 숨어 (P)\'보이지 않는 포식자\'를 활용해 압박하세요.', lv3: '애니비아가 (W)\'결정화\' 벽을 세우면 접근이 어려우니 벽이 생기기 전에 움직이세요. (Q)\'냉기 폭발\'을 피한 뒤 (E)\'올가미 투척\'을 맞히고 (Q)\'포악함\'으로 딜교환을 시도해요. (E)\'동상\' 피해가 강해지기 전에 빠르게 몰아붙이세요.', lv6: '(R)\'사냥의 전율\'로 위장 상태에서 접근해 (E)\'올가미 투척\'을 맞히는 것이 중요해요. (R)\'얼음 폭풍\' 장판이 깔리면 둔화 때문에 움직이기 힘드니 장판이 커지기 전에 진입하세요. 애니비아가 (P)\'환생\'으로 알이 되면 체력을 회복해 돌아오니, 부활한 뒤 다시 교전 각을 잡으세요.', item: '마법 저항력과 강인함을 얻기 위해 헤르메스의 발걸음을 신발로 선택하세요. 첫 코어는 전투 지속력을 높여주는 몰락한 왕의 검이 좋아요.', spell: '점멸과 점화를 추천해요. 점멸로 (Q)\'냉기 폭발\'의 기절을 피하고 점화로 애니비아의 체력을 깎아 마무리하세요.' },
    '야스오': { lv1: '야스오가 (Q)\'강철 폭풍\' 중첩을 쌓아 회오리바람으로 띄우기 전에 거리를 조절하며 (P)\'보이지 않는 포식자\'로 수풀에서 기습하세요. (P)\'낭인의 길\' 보호막이 있으니 먼저 평타를 쳐서 보호막을 제거한 뒤 (Q)\'포악함\'으로 딜교환을 시작해요.', lv3: '(E)\'올가미 투척\'은 투사체라 야스오의 (W)\'바람 장막\'에 막힐 수 있으니 장막이 빠진 후에 사용하세요. 야스오가 (E)\'질풍검\'으로 미니언을 타고 접근하는 경로를 예상해 (Q)\'포악함\'을 섞어 먼저 견제하세요. 피해를 받은 뒤에는 (W)\'전투의 포효\'로 체력을 회복하며 안정적으로 교전하세요.', lv6: '(R)\'사냥의 전율\'로 위장 상태에서 진입해 야스오의 방어력을 깎고 빠르게 몰아치세요. (Q)\'강철 폭풍\'의 회오리에 맞아 공중에 뜨면 (R)\'최후의 숨결\'로 이어지니 회오리가 준비된 야스오 앞에 정면으로 서지 말고, 수풀을 활용해 정글러를 부르세요.', item: '첫 코어 아이템으로 굶주린 히드라를 가서 체력 관리와 공격력을 챙기세요. 신발은 야스오의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 야스오의 보호막을 뚫고 체력이 낮은 적을 확실하게 마무리할 수 있어요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'을 사용해 사거리가 늘어난 평타로 방어력을 깎으며 압박해요. 수풀에서 (P)\'보이지 않는 포식자\'를 활용해 먼저 도약하며 짧게 딜교환을 하세요. 초반에는 오공의 평타 사거리에 조심하며 거리를 조절해야 해요.', lv3: '오공이 (W)\'분신 전사\'를 써서 투명해지면 진짜 위치를 잘 파악해야 해요. 오공이 (E)\'근두운 급습\'으로 들어올 때 (E)\'올가미 투척\'을 맞춰서 움직임을 늦추세요. 분신에 (E)\'올가미 투척\'을 낭비하지 않도록 주의하며 진짜 오공을 노려야 해요.', lv6: '오공이 (R)\'회전격\'을 사용하면 공중에 떠서 스킬을 쓸 수 없으니 주의하세요. (R)\'사냥의 전율\'로 위장 상태가 되어 접근한 뒤 오공의 궁극기가 빠진 타이밍에 (Q)\'포악함\'을 사용하세요. 오공이 궁극기를 사용하면 무리하게 싸우지 말고 거리를 유지하며 라인을 관리하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 전투 지속력을 높이세요. 신발은 오공의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 오공에게 추가 피해를 입혀 킬각을 잡으세요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'를 던진 후 다시 불러들여 피해를 입히니 궤적을 피해 움직이세요. (P)\'보이지 않는 포식자\'로 수풀에서 도약해 (Q)\'포악함\'으로 빠르게 피해를 주고 빠지세요. (Q)\'이중 저주\'의 두 번째 타격에 맞지 않게 주의하며 거리를 조절하세요.', lv3: '(E)\'마법의 문\'은 둔화를 걸고 오로라가 뒤로 도약하니 이 스킬이 빠진 뒤에 진입하세요. 최대 야성 상태의 (E)\'올가미 투척\'으로 속박시킨 뒤 (Q)\'포악함\'으로 빠르게 압박하세요. (W)\'장막 너머로\'로 투명해진 오로라를 무리하게 쫓지 말고 다음 도약 기회를 기다리세요.', lv6: '(R)\'세계의 경계\' 영역 안에서는 둔화가 심하고 오로라의 이동이 자유로우니 영역 밖에서 기회를 보세요. (R)\'사냥의 전율\'로 접근해 상대의 (E)\'마법의 문\'이 빠진 순간 도약하며 방어력을 깎으세요. 최대 야성 상태의 (W)\'전투의 포효\'로 둔화를 해제하며 추격해 킬각을 잡으세요.', item: '맬모셔스의 아귀를 첫 코어로 가서 마법 저항력을 높이고 생명선 보호막으로 폭딜을 버티세요. 신발은 (E)\'마법의 문\'과 (R)\'세계의 경계\'의 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 오로라가 (P)\'영혼 방호술\'로 체력을 회복하므로 점화로 회복 효과를 억제하며 마무리하세요.' },
    '오른': { lv1: '오른은 (P)\'간이 대장간\' 덕분에 초반 방어력과 마법 저항력이 높고 (Q)\'용암 균열\'로 둔화를 걸며 압박해요. (Q)\'용암 균열\'이 생기는 위치를 미리 확인하여 피하고 수풀을 활용해 (Q)\'포악함\'을 섞은 짧은 교환을 시도하세요.', lv3: '(E)\'화염 돌진\'이 지형지물에 부딪혀 에어본을 발생시키니 벽 근처에서는 주의하세요. (W)\'불꽃 풀무질\'의 마지막 불꽃에 맞으면 불안정 상태가 되니 전진하는 방향을 조심해야 해요. (E)\'올가미 투척\'을 먼저 맞춰 둔화를 걸고 수풀에서 접근하여 딜교환을 하세요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 접근한 뒤 (E)\'올가미 투척\'으로 상대를 묶고 공격하세요. (R)\'대장장이 신의 부름\'의 정령이 공중으로 띄워 올리면 스킬을 쓸 수 없고 (W)\'전투의 포효\'로도 풀 수 없으니 정령이 지나가는 길목을 피하세요. 오른의 (E)\'화염 돌진\'이 벽에 부딪히면 공중으로 뜨니 벽 근처도 조심하세요.', item: '탱커인 오른의 체력을 깎기 위해 몰락한 왕의 검을 첫 코어로 선택하세요. 신발은 오른의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화를 사용해 확실한 피해를 입히고 킬각을 잡는 것이 중요해요.' },
    '올라프': { lv1: '올라프가 (Q)\'역류\'로 도끼를 던져 방어력과 이동 속도를 깎으며 다가오니 수풀을 활용해 (P)\'보이지 않는 포식자\'로 짧게 딜교하세요. 도끼가 떨어지는 위치를 파악하며 거리를 조절하고 1~2레벨에는 무리하게 붙지 마세요. 올라프의 초반 맞딜이 강한 구간이니 체력 관리에 집중하며 라인을 받아먹어야 해요.', lv3: '(E)\'올가미 투척\'을 맞혀 올라프의 움직임을 제약하며 (Q)\'포악함\'을 섞어 딜교하세요. 올라프가 (W)\'버티기\'를 사용해 보호막과 공격 속도를 얻는 동안에는 맞붙지 말고 거리를 두는 것이 좋아요. 올라프의 (Q)\'역류\'가 빠진 타이밍에 야성을 활용해 진입하세요.', lv6: '올라프가 (R)\'라그나로크\'를 쓰면 이동 방해 효과에 면역이 되니 (E)\'올가미 투척\'으로 묶으려 하지 말고 거리를 벌리세요. (R)\'사냥의 전율\'로 위장 상태에서 접근해 방어력을 낮춘 뒤 빠르게 몰아쳐야 해요. (R)\'라그나로크\'가 끝난 뒤를 노리거나 정글러를 불러 함께 압박하세요.', item: '첫 코어로 몰락한 왕의 검을 선택해 전투 지속력을 높이세요. 신발은 올라프의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 올라프의 (P)\'광전사의 분노\'를 통한 생명력 흡수를 억제하세요.' },
    '요네': { lv1: '요네가 (Q)\'필멸의 검\'을 두 번 맞히면 돌진하며 공중으로 띄우니 첫 타를 맞았다면 거리를 벌려 두 번째 공격을 피하세요. 수풀에서 (P)\'보이지 않는 포식자\'로 도약해 짧게 공격하고 빠르게 빠지며 체력을 깎으세요. (P)\'사냥꾼의 길\'로 인한 두 번째 평타 마법 피해를 주의하며 짧은 교환만 유지하세요.', lv3: '(W)\'영혼 가르기\'의 보호막이 켜져 있을 때는 (Q)\'포악함\'의 피해가 상쇄되니 보호막이 사라진 뒤에 공격하세요. (E)\'영혼해방\'을 사용해 영혼이 나간 요네를 쫓지 말고 육신 근처에서 기다리다 돌아오는 타이밍에 최대 야성 (E)\'올가미 투척\'으로 속박하세요. 요네의 (Q)\'필멸의 검\' 돌풍처럼 공중에 띄우는 효과는 (W)\'전투의 포효\'로 풀 수 없으니 돌풍이 준비되면 정면에서 비켜서세요.', lv6: '(R)\'사냥의 전율\'로 위장해 접근한 뒤 도약하여 방어력을 깎고 순식간에 폭발적인 피해를 입히세요. 요네가 (R)\'운명봉인\'으로 끌어당길 때 정글러가 함께 진입하면 위험하니 강가 시야가 없을 때는 라인을 당겨 두세요. (E)\'영혼해방\'으로 요네가 돌아오는 지점에 (E)\'올가미 투척\'을 던져 두면 (R)\'운명봉인\'을 쓰기 전에 발을 묶기 편해요.', item: '몰락한 왕의 검을 첫 코어로 가서 생명력 흡수와 공격 속도로 지속 교전 능력을 높이세요. 신발은 요네의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'영혼 가르기\'의 보호막이 사라진 직후 점화로 마무리 피해를 입히는 것이 좋아요.' },
    '요릭': { lv1: '요릭이 (Q)\'최후의 의식\'으로 무덤을 만들고 (P)\'영혼의 길잡이\'로 망령을 소환하며 압박해요. 무덤이 쌓이기 전에 (Q)\'포악함\'으로 짧게 딜교환을 하고 수풀로 빠르게 숨으세요. 망령이 많을 때는 억지로 붙지 말고 거리 조절을 하며 기회를 보세요.', lv3: '(E)\'애도의 안개\'에 맞으면 표식이 남고 망령이 몰려오니 구체가 날아오는 방향을 보고 피하세요. 야성을 모아 (E)\'올가미 투척\'으로 요릭을 속박하고 빠르게 몰아붙여야 해요. 요릭이 (W)\'망자의 진\'으로 가두려 하면 벽을 빠르게 공격해 부수고 빠져나오세요.', lv6: '(R)\'사냥의 전율\'로 위장해 접근한 뒤 방어력을 깎고 빠르게 공격하세요. (R)\'군도의 장송곡\'으로 소환된 마녀가 합세하면 지속 싸움이 힘드니 짧은 호흡으로 딜교환을 하세요. 피해를 입었을 때는 (W)\'전투의 포효\'를 사용해 체력을 회복하며 버티세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 공격 속도와 생명력 흡수를 챙기세요. 신발은 요릭과 망령의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 요릭이 (Q)\'최후의 의식\'으로 회복하는 양을 점화로 줄여서 빠르게 처치해야 해요.' },
    '우디르': { lv1: '우디르가 (Q)\'야생 발톱\' 태세로 평타 사거리를 늘려 공격할 때 (E)\'올가미 투척\'으로 거리를 유지하며 견제하세요. 우디르가 (E)\'불길 쇄도\'를 사용하여 돌진하면 기절을 맞을 수 있으니 수풀 근처에서 조심하며 대응하세요. 1~2레벨에는 무리하게 맞붙기보다 미니언을 챙기며 야성을 쌓는 것이 좋아요.', lv3: '우디르가 (W)\'강철 갑옷\'으로 보호막을 얻었을 때는 (Q)\'포악함\'을 활용한 딜교환을 잠시 멈추세요. 우디르가 (E)\'불길 쇄도\'로 돌진하여 기절을 시도하면 (E)\'올가미 투척\'으로 둔화를 걸어 대응하세요. 야성이 쌓여 (W)\'전투의 포효\'를 쓸 수 있다면 우디르의 군중 제어 효과를 풀며 반격할 수 있어요.', lv6: '(R)\'사냥의 전율\'을 사용하여 위장 상태로 우디르의 뒤를 잡고 (E)\'올가미 투척\'으로 속박을 노리세요. 우디르가 (E)\'불길 쇄도\'를 재사용하여 이동 불가 효과에 면역이 된 상태라면 무리하게 기술을 맞히려 하지 마세요. 우디르가 (R)\'날개 돋친 폭풍\'을 켜고 주변에 둔화를 뿌릴 때는 거리 조절에 신경 쓰며 진입 타이밍을 잡으세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력이 높은 우디르를 압박하세요. 신발은 우디르의 (E)\'불길 쇄도\' 기절과 마법 피해를 고려해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 우디르의 (W)\'강철 갑옷\' 회복 효과를 줄여 킬각을 잡기에 좋아요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'으로 둔화를 걸고 (P)\'화염의 메아리\'로 평타 견제를 하니 거리를 조절하세요. 수풀에서 (Q)\'포악함\'으로 빠르게 진입해 짧은 딜교환을 하고 우르곳의 사거리 밖으로 즉시 빠져나오는 리듬을 유지하세요. 평타 견제가 강한 구간이니 무리하게 붙지 말고 막타만 챙기며 기회를 보세요.', lv3: '우르곳이 (E)\'경멸\'로 돌진하며 나를 뒤로 던지려 할 때 옆으로 비켜서서 기절되는 상황을 피하세요. (E)\'경멸\'이 빠진 틈을 타 (E)\'올가미 투척\'으로 상대를 묶고 (Q)\'포악함\'과 (W)\'전투의 포효\'를 섞어 빠르게 체력을 깎으세요. (W)\'심판의 원\'이 켜져 있을 때는 무리하게 붙지 말고 사격이 끝날 때까지 기다렸다가 진입하세요.', lv6: '(R)\'사냥의 전율\'을 켜고 위장 상태에서 도약해 우르곳의 방어력을 깎으며 기습적으로 공격하세요. (R)\'불사의 공포\' 섬광탄에 맞은 뒤 체력이 낮아지면 제압당해 처형될 수 있으니 즉시 거리를 벌려 안전하게 회복하세요. 라인 관리를 통해 정글러가 개입하기 좋은 구도를 만들고 상대의 주요 스킬이 빠진 순간에 킬각을 잡으세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 체력이 높은 우르곳에게 퍼센트 피해를 입히세요. 신발은 우르곳의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 우르곳이 (R)\'불사의 공포\'로 처형하기 전에 점화의 추가 피해로 빠르게 마무리하세요.' },
    '워윅': { lv1: '워윅은 (Q)\'야수의 송곳니\'로 도약하며 입힌 피해만큼 체력을 회복하니 1~2레벨에는 직접적인 맞대결을 피하세요. 수풀에서 (P)\'보이지 않는 포식자\'를 활용해 도약 공격으로 견제하며 워윅의 체력을 먼저 깎아 두는 것이 좋아요. 워윅의 체력이 낮아지면 (P)\'끝없는 허기\'로 인해 회복량이 늘어나니 주의하세요.', lv3: '워윅이 (E)\'원시의 포효\'를 사용하면 받는 피해가 줄어드니 그 지속 시간 동안에는 딜교환을 아끼세요. 포효가 끝나면 공포가 발동되니 그 전에 (E)\'올가미 투척\'을 맞춰 거리를 조절하세요. 공포에 걸리면 스킬을 쓸 수 없으니 포효 범위에서 미리 벗어나는 것이 중요해요.', lv6: '(R)\'사냥의 전율\'을 사용하여 위장 상태로 접근해 방어력을 낮추고 빠르게 몰아치세요. 워윅의 (R)\'무한의 구속\'에 제압되면 점멸이나 스킬을 사용할 수 없으니 조심해야 해요. 제압은 정화로 풀 수 없으니 워윅의 궁극기가 남아 있을 때는 체력이 낮은 상태로 라인을 밀지 마세요.', item: '첫 코어로 몰락한 왕의 검을 선택해 공격력과 생명력 흡수를 챙기세요. 신발은 워윅의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 (Q)\'야수의 송곳니\'와 (P)\'끝없는 허기\'를 통한 회복을 억제하세요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'를 미니언에 사용하여 체력을 회복하며 빠르게 접근해요. 낮은 체력의 미니언 근처를 피하며 거리 조절을 하고 (Q)\'포악함\'을 활용해 짧게 딜교환을 하세요.', lv3: '이렐리아가 (E)\'쌍검협무\'로 기절시키고 표식을 남기면 (Q)\'칼날 쇄도\'로 계속 들어올 수 있으니 주의하세요. (W)\'저항의 춤\'이 활성화된 동안에는 물리 피해가 감소하니 (Q)\'포악함\'을 아꼈다가 효과가 끝난 뒤 사용해요. 최대 야성일 때 (E)\'올가미 투척\'으로 이렐리아를 묶으면 대응하기 편해요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 진입하여 (Q)\'칼날 쇄도\'를 쓰기 전에 방어력을 깎고 공격하세요. 이렐리아의 (R)\'선봉진격검\' 결계가 생성되면 둔화에 걸려 위험하니 결계 밖으로 빠르게 위치를 옮기세요. (E)\'쌍검협무\'가 빠진 타이밍에 도약해서 강력하게 몰아붙이면 킬을 노릴 수 있어요.', item: '몰락한 왕의 검을 첫 코어로 선택해 맞딜 능력을 높이세요. 신발은 이렐리아의 기본 공격 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화. 점화로 (Q)\'칼날 쇄도\'의 체력 회복 효과를 억제하여 킬각을 잡으세요.' },
    '일라오이': { lv1: '일라오이의 촉수는 근처 지형에 소환되어 적을 때리니 벽 근처에서 오래 싸우지 마세요. 수풀에서 (P)\'보이지 않는 포식자\'로 도약해 (Q)\'포악함\'으로 짧게 교환하고 빠지세요. 일라오이가 (W)\'혹독한 가르침\'으로 돌진해 올 때는 촉수까지 함께 맞으니 거리를 조절하세요.', lv3: '일라오이가 (E)\'영혼의 시험\'을 사용하면 분리된 영혼이 입는 피해 일부가 본체로 전이되니 영혼을 잘 관리하세요. 영혼에서 너무 멀어지면 숙주가 되어 촉수를 소환하게 되니 주의하고, (E)\'올가미 투척\'을 맞춘 뒤 야성을 쌓아 (Q)\'포악함\'으로 몰아붙이세요.', lv6: '일라오이가 (R)\'믿음의 도약\'으로 많은 촉수를 소환하면 그 범위 안에서 싸우지 말고 즉시 거리를 벌리세요. (R)\'사냥의 전율\'을 사용해 위장 상태로 접근하며 일라오이의 방어력을 감소시키고, 촉수가 없는 곳에서 (W)\'전투의 포효\'로 체력을 관리하며 싸우세요.', item: '굶주린 히드라를 첫 코어로 올려서 강력한 공격력을 확보하고 전투를 이어나가세요. 신발은 일라오이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 일라오이의 촉수를 피해 점멸로 진입각을 만들고, 점화의 마무리 피해로 체력이 낮은 일라오이를 처치하세요.' },
    '자크': { lv1: '수풀에서 (P)\'보이지 않는 포식자\'를 활용해 기습적으로 도약하며 압박하세요. 자크의 (Q)\'탄성 주먹\'에 붙잡히면 둔화되며 미니언과 함께 공중으로 뜰 수 있으니 미니언과 겹치지 않게 서세요. 자크가 스킬을 쓰고 떨어진 조각을 (P)\'세포 분열\'로 흡수해 회복하지 못하도록 계속해서 공격하세요.', lv3: '자크가 (E)\'새총 발사\'를 준비하며 뒤로 늘어나는 모습이 보이면 즉시 옆으로 피하세요. (E)\'올가미 투척\'으로 자크의 발을 묶어 접근을 차단하고 (Q)\'포악함\'으로 빠르게 피해를 입히세요. 자크가 (W)\'불안정 물질\'로 주변에 피해를 줄 때 (W)\'전투의 포효\'를 사용해 체력을 회복하며 맞서세요.', lv6: '(R)\'사냥의 전율\'로 위장해 접근한 뒤 자크의 방어력을 깎고 폭발적인 피해를 입히세요. 자크의 (R)\'바운스!\'에 맞으면 공중에 떠서 스킬을 쓸 수 없으니 자크가 튀어 오르는 방향을 피해 움직이세요. 자크가 쓰러진 뒤 (P)\'세포 분열\' 조각으로 갈라지면 조각들을 빠르게 정리해 부활을 막으세요.', item: '체력이 높은 자크를 상대하기 위해 현재 체력 비례 피해를 주는 몰락한 왕의 검을 첫 코어로 가세요. 신발은 자크의 마법 피해를 줄이고 군중 제어 지속시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 자크가 (P)\'세포 분열\' 조각을 통해 체력을 회복하는 것을 억제하세요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 두 번 공격하며 체력을 회복하니 정면 평타 싸움은 피하세요. 수풀을 활용해 (P)\'보이지 않는 포식자\'로 도약하며 짧게 딜교하고 빠르게 빠져야 해요. 자헨이 (P)\'전쟁 단련\' 중첩을 쌓지 못하도록 거리 조절을 하며 첫 웨이브를 받아내세요.', lv3: '자헨의 (W)\'공포의 귀환\'이나 (Q)\'다르킨의 글레이브\' 재사용이 빠진 것을 확인하고 교전을 시작하세요. (E)\'올가미 투척\'을 맞춰 자헨의 움직임을 제약하고 (Q)\'포악함\'을 섞어 빠르게 피해를 입히세요. 자헨이 공중에 띄우는 공격을 하기 전에 (W)\'전투의 포효\'로 피해를 회복하며 대응하세요.', lv6: '(R)\'사냥의 전율\'로 위장 상태에서 접근해 방어력을 깎고 폭발적인 피해를 입히세요. 자헨이 (R)\'단호한 판결\'로 높이 날아오르면 낙하 지점을 피해 체력을 보존해야 해요. 결심 중첩이 가득 찬 자헨은 부활할 수 있으니 확실하게 처치한 뒤에도 주의를 기울이세요.', item: '첫 코어로 굶주린 히드라를 가서 공격력과 생명력 흡수를 챙기세요. 신발은 자헨의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 자헨이 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 회복하니 점화의 치유 감소가 필요해요.' },
    '잭스': { lv1: '1~2레벨에는 수풀을 활용해 (P)\'보이지 않는 포식자\'로 잭스의 허를 찌르며 짧게 교환하세요. 잭스가 (Q)\'도약 공격\'으로 붙으며 (W)\'무기 강화\'를 사용할 때는 거리를 조절하며 대응해요. 잭스의 (P)\'가차없는 맹공\'이 쌓이기 전에 수풀을 이용해 압박하는 것이 좋아요.', lv3: '잭스가 (E)\'반격\'을 켜면 기본 공격을 피하고 기절시키니 그동안은 (E)\'올가미 투척\'으로 거리만 유지하며 기다리세요. (E)\'반격\'이 끝난 직후에 (Q)\'포악함\'을 활용한 강화 평타로 딜교환을 시도하는 것이 좋아요. 잭스가 (Q)\'도약 공격\'으로 도망가지 못하도록 주의하며 스킬을 맞춰야 해요.', lv6: '(R)\'사냥의 전율\'을 켜고 위장 상태로 접근하여 잭스의 (E)\'반격\'이 빠진 타이밍을 노려 몰아치세요. 잭스가 (R)\'무기의 달인\'을 사용해 방어력을 높인 상태라면 정면 승부를 피하며 정글러의 개입을 기다려요. (E)\'올가미 투척\'으로 잭스를 속박시켜 (R)\'사냥의 전율\'의 추가 피해와 함께 킬각을 잡으세요.', item: '몰락한 왕의 검을 첫 코어로 가서 전투 지속력을 높이세요. 신발은 잭스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 잭스가 (Q)\'도약 공격\'으로 도망칠 때 확실하게 처치하세요.' },
    '제이스': { lv1: '제이스가 캐논 형태로 (Q)\'전격 폭발\'을 쏘며 멀리서 견제하니 직선 경로를 잘 피하며 체력을 보존하세요. 수풀을 활용해 (P)\'보이지 않는 포식자\'로 접근할 기회를 노리며 미니언과 함께 움직여야 해요. 1~2레벨에는 무리한 진입보다 거리 조절에 집중하며 성장하는 것이 좋아요.', lv3: '제이스가 해머 형태의 (E)\'천둥 강타\'로 밀쳐낼 수 있으니 그 스킬을 먼저 빼는 것이 중요해요. 제이스가 (E)\'천둥 강타\'를 허무하게 사용했다면 수풀에서 도약해 (E)\'올가미 투척\'으로 대상을 묶으세요. (W)\'전투의 포효\'를 사용하여 제이스의 견제 피해를 회복하며 딜교환을 시도하세요.', lv6: '(R)\'사냥의 전율\'로 위장 상태가 되어 접근한 뒤 (E)\'올가미 투척\'을 맞춰 제이스를 제자리에 묶으세요. 제이스가 (R)\'머큐리 캐논\'으로 변환해 방어력을 깎기 전에 (R)\'사냥의 전율\'의 도약으로 빠르게 접근해야 해요. 제이스가 (E)\'가속 관문\'을 통해 도망치기 전에 (Q)\'포악함\'을 섞은 공격으로 킬각을 잡으세요.', item: '몰락한 왕의 검을 첫 코어로 구매하여 전투 지속력을 높이세요. 신발은 제이스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 제이스가 거리를 벌리기 전에 점화로 피해를 입혀 킬을 확정하세요.' },
    '초가스': { lv1: '초가스는 (Q)\'파열\'로 지정한 지역을 공중으로 띄우고 둔화를 걸기에 지면이 부풀어 오르는 표시를 보고 범위를 벗어나세요. 수풀을 활용해 (P)\'보이지 않는 포식자\'의 도약을 준비하며 초가스의 (E)\'날카로운 가시\' 정면을 피하며 딜교환해요. 1~2레벨에는 초가스가 (P)\'육식\'으로 미니언을 처치하며 체력을 회복하지 못하도록 막타 타이밍에 맞춰 견제하세요.', lv3: '초가스가 (W)\'흉포한 울부짖음\'을 사용하면 침묵에 걸려 스킬을 쓸 수 없으니 원뿔 범위 밖으로 빠르게 움직여요. (E)\'올가미 투척\'으로 초가스를 둔화시켜 거리를 조절하고, 해당 스킬이 빠진 타이밍에 (Q)\'포악함\'을 섞은 도약 공격을 시도하세요. (Q)\'파열\'은 지정한 지역에 있는 적을 띄우니 지면 표시가 보이면 범위 밖으로 벗어나세요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 접근하여 초가스의 방어력을 낮춘 뒤 폭발적인 피해를 입혀요. 초가스가 (R)\'포식\'을 사용하면 큰 고정 피해를 입히므로 체력이 낮을 때는 무리하게 진입하지 말고 조심하세요. (R)\'사냥의 전율\'로 도약할 때 초가스의 (Q)\'파열\' 위치를 확인하여 공중으로 뜨지 않도록 주의하며 킬각을 보세요.', item: '첫 코어 아이템으로 굶주린 히드라를 선택해 공격력과 생명력 흡수를 챙기세요. 신발은 초가스의 마법 피해와 (W)\'흉포한 울부짖음\'의 침묵 지속 시간을 줄여주는 헤르메스의 발걸음을 신으세요.', spell: '점멸과 점화를 추천해요. 점화로 초가스의 (P)\'육식\'을 통한 체력 회복 효과를 줄여 킬을 결정지으세요.' },
    '카밀': { lv1: '카밀은 (Q)\'정확성 프로토콜\'로 이동 속도를 높이며 강화 평타를 넣고, (P)\'적응형 방어 체계\'로 보호막을 얻어요. 1~2레벨에는 카밀이 평타를 칠 때 생기는 보호막을 조심하고, (Q)\'정확성 프로토콜\'을 재사용하여 가하는 강화 공격이 빠진 뒤에 (Q)\'포악함\'으로 딜교환하세요.', lv3: '(W)\'전술적 휩쓸기\'의 바깥쪽 절반에 맞으면 둔화되고 카밀이 체력을 회복하니, 최대한 안쪽으로 파고들거나 범위 밖으로 벗어나세요. 카밀이 (E)\'갈고리 발사\'로 들어오는 돌진은 둔화로 막을 수 없으니 착지 지점에서 비켜서고, 착지한 뒤 최대 야성 (E)\'올가미 투척\'으로 속박하세요. 카밀의 (E)\'갈고리 발사\'가 빠진 타이밍에 (Q)\'포악함\'과 (W)\'전투의 포효\'를 섞어 짧게 교환하고 빠지세요.', lv6: '(R)\'마법공학 최후통첩\'에 갇히면 어떤 방법으로도 탈출할 수 없으니, 카밀이 궁극기를 쓰기 전에 (R)\'사냥의 전율\'로 먼저 도약해 방어력을 깎으세요. (R)\'마법공학 최후통첩\' 사용 직후 카밀의 기본 공격 마법 피해가 강력하므로, (W)\'전투의 포효\'로 피해를 회복하며 버티세요. 라인 관리 중 카밀이 (E)\'갈고리 발사\'로 벽을 넘어 정글러와 덮칠 수 있으니 항상 시야를 확인하세요.', item: '독사의 송곳니를 첫 코어로 선택해 카밀의 (P)\'적응형 방어 체계\' 보호막을 빠르게 제거하세요. 신발은 카밀의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 카밀이 (W)\'전술적 휩쓸기\'로 체력을 회복하는 것을 점화의 치유 감소로 억제하세요.' },
    '카사딘': { lv1: '1~2레벨에는 (Q)\'무의 구체\'로 보호막을 얻으며 견제하는 카사딘의 사거리를 조심하며 수풀을 활용하세요. 수풀에서 (Q)\'포악함\'을 섞은 공격으로 초반 주도권을 가져오며 적절한 거리를 유지해야 해요.', lv3: '(E)\'올가미 투척\'을 적중시켜 카사딘의 이동을 방해하며 딜교환을 시작하세요. 상대의 (E)\'힘의 파동\'을 피하거나 맞은 뒤 (Q)\'포악함\'으로 빠르게 몰아붙이며 야성 중첩을 쌓는 것이 중요해요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 접근하여 방어력을 깎고 기습적으로 킬각을 잡으세요. 카사딘이 (R)\'균열 이동\'으로 거리를 벌리며 도망칠 수 있으니 진입 타이밍을 신중하게 정해야 해요.', item: '헤르메스의 발걸음과 굶주린 히드라를 추천해요. 마법 저항력을 높여 마법 피해를 견디고 생명력 흡수로 전투 지속력을 높이기 위해서예요.', spell: '점멸과 점화를 추천해요. 카사딘의 도주를 막고 강력한 피해를 입혀 적을 빠르게 처치하기 위해서예요.' },
    '카시오페아': { lv1: '(Q)\'맹독 폭발\'을 이용한 견제를 조심하며 수풀을 활용해 거리를 조절하세요. (Q)\'포악함\'을 사용해 미니언을 정리하며 상대의 독이 묻은 상태에서 (E)\'쌍독니\'를 맞지 않도록 주의해야 해요.', lv3: '(W)\'독기의 늪\'이 사용된 것을 확인한 뒤 (E)\'올가미 투척\'을 맞혀 둔화를 걸고 거리를 좁히세요. 늪에 빠지면 이동 스킬을 사용할 수 없으니 독구름 위로 들어가지 말고, (E)\'쌍독니\'는 중독된 상대에게 더 아프니 독에 맞은 상태에서는 거리를 두세요. 야성 중첩을 쌓아 (W)\'전투의 포효\'로 상대의 군중 제어 효과를 해제하세요.', lv6: '(R)\'사냥의 전율\'로 위장 상태에서 진입할 때 (R)\'석화의 응시\'를 정면으로 맞지 않도록 방향을 조절하세요. (E)\'올가미 투척\'으로 상대를 묶고 빠르게 피해를 입히면 킬을 노릴 수 있어요. 정글러를 호출하여 압박하거나 라인을 밀어 넣으세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 추천해요. 마법 저항력을 높여 (E)\'쌍독니\'의 피해를 견디고 전투 지속력을 높여줘요. 상대의 마법 피해에 대응하기에 적절해요.', spell: '점멸과 점화예요. (E)\'쌍독니\'를 통한 상대의 체력 회복을 억제하고 확실하게 적을 처치하기 위해 선택해요. 돌발적인 진입을 위해서도 유용해요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'을 던져 멀리서 (P)\'폭풍의 표식\'을 쌓으려 해요. 미니언 뒤에 숨어 수리검을 피하고 수풀을 활용해 (P)\'보이지 않는 포식자\'로 기습해 짧게 교환하세요. 표식이 모두 쌓이면 기절하니 무리하게 붙지 말고 거리를 조절하세요.', lv3: '케넨이 (E)\'번개 질주\'로 빠르게 접근하거나 도망갈 때 (E)\'올가미 투척\'을 맞춰 속박하고 (Q)\'포악함\'으로 강하게 공격하세요. (W)\'전류 방출\'로 표식이 빠르게 쌓여 기절이 걸릴 수 있으니, 표식이 쌓인 시점에서는 잠시 물러나 표식이 사라지길 기다려요. 기절 중에는 스킬을 쓸 수 없으니 표식이 쌓이기 전에 교환을 마치세요.', lv6: '(R)\'사냥의 전율\'로 위장해 접근한 뒤 케넨이 (R)\'날카로운 소용돌이\'를 켜기 전에 도약해 빠르게 제압하세요. 만약 케넨이 궁극기를 사용해 방어력과 마법 저항력을 얻었다면 무리하게 진입하지 말고 폭풍이 끝날 때까지 기다리세요. 기절이 걸리기 전에 (E)\'올가미 투척\'으로 거리를 좁히고 정글러의 개입을 유도해 킬각을 잡으세요.', item: '마법사의 최후를 첫 코어로 가서 마법 저항력과 강인함을 얻어 케넨의 기절 시간을 줄이세요. 신발은 헤르메스의 발걸음을 신어 마법 저항력을 높이고 강인함으로 군중 제어 지속시간을 낮추세요.', spell: '점멸과 정화를 추천해요. 케넨의 (P)\'폭풍의 표식\'으로 인한 기절을 정화로 즉시 풀어 다시 공격할 수 있어요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'으로 레벨이 오를수록 강해지는 성장이 필요한 구간이에요. 수풀에서 (P)\'보이지 않는 포식자\'를 활용해 도약하며 초반 압박을 이어가세요. 케일의 (Q)\'광휘의 일격\' 궤적을 피하며 방어력과 마법 저항력이 깎이지 않게 주의해요.', lv3: '(E)\'올가미 투척\'으로 케일을 둔화시킨 뒤 (Q)\'포악함\'을 섞어 빠르게 접근하세요. 케일이 (E)\'화염주문검\'의 사용 효과로 잃은 체력 비례 피해를 입히기 전에 먼저 딜교환을 시작하는 게 좋아요. 케일의 (W)\'천상의 축복\' 회복을 고려해 전투를 빠르게 끝내세요.', lv6: '(R)\'사냥의 전율\'로 케일의 방어력을 낮추며 진입하되 (R)\'신성한 심판\'의 무적 상태를 조심하세요. 케일의 무적이 끝나면 즉시 (E)\'올가미 투척\'을 맞춰 둔화를 걸고 (Q)\'포악함\'으로 마무리해요. 케일이 성장을 마치기 전에 정글러를 불러 빠르게 킬을 노리세요.', item: '첫 코어로 굶주린 히드라를 선택해 생명력 흡수와 라인 클리어를 챙기세요. 신발은 케일의 마법 피해를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 케일의 (W)\'천상의 축복\'으로 인한 체력 회복을 억제하며 킬각을 잡으세요.' },
    '코그모': { lv1: '1~2레벨 구간에서는 코그모가 (Q)\'부식성 침\'을 사용하여 방어력을 낮추고 견제하는 힘이 강해요. 미니언 뒤에 숨어 (Q)\'부식성 침\'의 피해를 최대한 피하며 첫 웨이브를 안정적으로 받아내요. 수풀을 활용해 (P)\'보이지 않는 포식자\'의 도약 이점을 챙기며 접근 기회를 엿보세요.', lv3: '3레벨이 되면 (E)\'올가미 투척\'을 적중시켜 둔화를 걸며 빠르게 진입해요. 코그모가 (E)\'공허의 분비물\'을 사용하여 이동 속도를 늦추려 하면 (W)\'전투의 포효\'로 제어 효과를 해제하며 계속 압박해요. (Q)\'포악함\'의 강화된 공격을 섞어 짧은 딜교환을 시도해요.', lv6: '6레벨 이후에는 (R)\'사냥의 전율\'을 사용해 위장 상태로 진입하며 코그모의 방어력을 낮추고 킬각을 노려요. 코그모가 (R)\'살아있는 곡사포\'를 사용하면 위치가 드러날 수 있으니 수풀을 적절히 활용하며 접근해야 해요. 정글러의 개입을 유도하며 빠르게 전투를 끝내도록 해요.', item: '헤르메스의 발걸음과 굶주린 히드라를 가요. 코그모의 마법 피해를 견디고 생명력 흡수로 전투를 지속하기 위해서예요.', spell: '점멸과 점화. 코그모를 빠르게 처치하기 위해 사용해요.' },
    '코르키': { lv1: '코르키의 (Q)\'인광탄\' 사거리 내에서 무리하게 미니언을 먹기보다 거리를 조절하며 버텨요. 수풀에 숨어 (P)\'보이지 않는 포식자\'를 통해 다음 공격을 준비하며 기회를 기다려요.', lv3: '(E)\'올가미 투척\'을 적중시켜 코르키를 둔화시킨 뒤 (Q)\'포악함\'을 활용해 빠르게 공격해요. 코르키의 (E)\'개틀링 건\'에 방어력이 깎이며 피해를 입었다면 그 뒤에 (W)\'전투의 포효\'로 입은 피해를 회복하며 싸워요.', lv6: '(R)\'사냥의 전율\'을 사용하여 위장 상태로 진입하며 코르키의 (R)\'미사일 폭격\'이 빠진 순간을 노려요. (E)\'올가미 투척\'의 야성 효과로 속박을 걸어 확실하게 킬을 노리고 정글러를 불러요.', item: '헤르메스의 발걸음과 굶주린 히드라를 가요. 마법 저항력을 얻고 생명력 흡수로 라인 유지력을 높여요.', spell: '점멸과 점화. 코르키의 체력을 빠르게 깎아 킬을 확정하기 위해 선택해요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식이 남은 상태에서 첫 기본 공격이 매우 강력하니 표식이 보이면 거리를 두세요. 수풀에서 (P)\'보이지 않는 포식자\'를 활용해 도약하며 압박하되, 퀸의 (Q)\'실명 공격\'에 맞아 시야가 좁아지는 것을 주의해야 해요. 1~2레벨 구간에는 무리하게 맞붙기보다 수풀을 이용해 거리 조절을 하며 퀸의 견제를 피하세요.', lv3: '퀸이 (E)\'공중제비\'로 진입한 뒤 뒤로 물러날 때 (E)\'올가미 투척\'을 맞춰 대상을 묶어두는 것이 중요해요. 퀸의 (Q)\'실명 공격\'을 맞았다면 시야가 제한되니 주의하며 (W)\'전투의 포효\'로 체력을 회복하며 버티세요. 야성을 쌓아 (E)\'올가미 투척\'으로 퀸을 제자리에 묶을 수 있다면 적극적으로 (Q)\'포악함\'을 섞어 딜교환을 하세요.', lv6: '(R)\'사냥의 전율\'을 사용하여 위장 상태로 접근해 퀸의 방어력을 낮추고 한 번에 몰아붙이세요. 퀸이 (R)\'후방 지원\'을 사용해 빠르게 이동하려 한다면 도약하여 (E)\'올가미 투척\'으로 묶고 추격해야 해요. 퀸이 (E)\'공중제비\'로 밀어내기 전에 (R)\'사냥의 전율\'로 빠르게 진입하는 타이밍이 킬각을 잡기에 좋아요.', item: '퀸의 기본 공격 피해를 줄이기 위해 판금 장화를 선택하세요. 첫 코어 아이템으로는 굶주린 히드라를 구매하여 공격력과 생명력 흡수를 챙기는 것이 좋아요.', spell: '점멸과 점화를 추천해요. 퀸의 낮은 체력을 바탕으로 기습 시 점화로 확실하게 마무리할 수 있어요.' },
    '크산테': { lv1: '크산테가 (Q)\'엔토포 타격\'으로 둔화를 걸며 압박할 때 수풀을 활용해 거리 조절을 하세요. 1~2레벨에는 (Q)\'포악함\'을 활용해 짧게 치고 빠지는 딜교환을 시도하세요. 상대의 (Q)\'엔토포 타격\' 중첩이 쌓여 충격파가 나오기 전에 뒤로 물러나야 해요.', lv3: '최대 야성 상태에서 (E)\'올가미 투척\'으로 크산테를 속박한 뒤 (Q)\'포악함\'으로 피해를 입히세요. 크산테가 (W)\'길을 여는 자\'를 충전하면 저지 불가 상태로 돌진해 기절시키니 옆으로 피해 주세요. (E)\'발놀림\'으로 보호막을 얻으며 진입하는 시점을 피해 (W)\'전투의 포효\'로 체력을 회복하며 버티세요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 도약하면 크산테의 방어력을 깎아 큰 피해를 줄 수 있어요. 크산테가 (R)\'총공세\'를 사용하면 적을 벽 너머로 밀어내며 방어력이 낮아지니, 벽 근처에서 조심하며 이 기회에 집중적으로 공격하세요. 상대 정글러가 개입하기 쉬운 구도인지 항상 확인하며 딜교환을 이어 가세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력이 많은 크산테에게 높은 피해를 입히세요. 신발은 크산테의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'총공세\' 상태에서 증가하는 크산테의 체력 회복 효과를 억제하고 킬각을 잡으세요.' },
    '클레드': { lv1: '클레드가 (Q)\'덫날리기\'로 끌어당기며 싸우는 1~2레벨 구간은 거리를 조절하며 버티는 것이 중요해요. 수풀 근처에서 대기하다가 (P)\'보이지 않는 포식자\'를 활용해 짧게 딜교환을 시도하세요. 클레드의 (Q)\'덫날리기\'를 맞았다면 즉시 클레드에게서 멀어져서 추가 피해를 받지 않도록 주의하세요.', lv3: '클레드가 (W)\'버럭버럭\'을 사용해 공격 속도가 빨라진 상태에서는 정면 승부를 피해야 해요. 클레드의 (E)\'이랴!\' 돌진이 빠진 타이밍에 (E)\'올가미 투척\'으로 둔화를 걸고 (Q)\'포악함\'을 활용해 딜교환을 하세요. 야성 중첩이 쌓였을 때 (W)\'전투의 포효\'를 사용하면 클레드의 군중 제어 효과를 해제하며 안정적으로 회복할 수 있어요.', lv6: '클레드가 (R)\'돌겨어어억!!!\'로 돌진해올 때는 경로를 예측해 옆으로 움직여 스칼의 돌격 피해와 밀어내기를 피하세요. 클레드가 스칼에서 내린 상태라면 (R)\'사냥의 전율\'을 사용해 위장 상태에서 도약한 뒤 (Q)\'포악함\'과 함께 빠르게 처치하세요. 라인을 당겨두면 클레드가 스칼을 다시 타기 전에 정글러와 함께 압박하기 좋아요.', item: '몰락한 왕의 검을 첫 코어로 선택해 클레드의 체력을 깎고 생명력 흡수를 챙기세요. 신발은 클레드의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 스칼에서 내린 클레드는 챔피언에 대한 피해량이 줄어 처치하기 쉬우니 점화의 마무리 피해로 확실하게 끝내세요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 처음 맞는 유닛에게 피해를 주니 미니언 뒤에 서서 막으세요. 수풀에서 (Q)\'포악함\'으로 짧게 치고 빠지며 (P)\'절대 미각\' 중첩이 세 번 쌓이지 않게 주의하세요. 1~2레벨에는 무리하게 붙지 말고 짧은 교환만 반복하세요.', lv3: '탐 켄치가 (W)\'심연 잠수\'를 사용해 공중에 띄우면 스킬을 쓸 수 없으니 표시 범위를 빠르게 벗어나세요. (E)\'두꺼운 피부\' 보호막이 켜진 동안에는 공격을 아끼고 보호막이 사라진 뒤에 (E)\'올가미 투척\'으로 속박을 거세요. 최대 야성 상태의 (W)\'전투의 포효\'를 사용해 탐 켄치의 군중 제어 효과를 해제하며 대응하세요.', lv6: '(R)\'사냥의 전율\'로 진입해 상대의 방어력을 낮춘 뒤 강력하게 공격하세요. (P)\'절대 미각\' 중첩이 세 번 쌓인 상태에서 (R)\'집어삼키기\'에 먹히지 않도록 거리 조절에 신경 쓰세요. 탐 켄치가 (W)\'심연 잠수\'로 도망치면 바로 라인을 밀어 넣고 정글러를 부르세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 체력이 높은 탐 켄치에게 더 많은 피해를 입히세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 신어 군중 제어 지속 시간을 줄이세요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'혀 채찍\'과 (E)\'두꺼운 피부\'의 체력 회복 효과를 억제하세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 훔치고 둔화를 걸며 1~2레벨 구간에서 강하게 압박해요. 수풀에 숨어 (P)\'보이지 않는 포식자\'를 활용해 먼저 도약하며 딜교환을 시도하세요. 트런들이 (Q)\'깨물기\'를 사용해 공격력을 뺏으려 하면 둔화에 걸리지 않게 주의하며 대응하세요.', lv3: '트런들이 (W)\'얼음 왕국\'을 사용하면 영역 안에서의 공격 속도와 회복량이 늘어나니 영역 밖에서 싸우세요. (E)\'올가미 투척\'을 먼저 맞혀 둔화를 걸고 딜교환을 시도하되, 트런들의 (E)\'얼음 기둥\'에 밀려나지 않도록 조심하세요. (Q)\'포악함\'을 섞어 야성 중첩을 쌓으며 공격적으로 움직여야 해요.', lv6: '트런들이 (R)\'진압\'을 사용하면 체력과 방어력을 뺏기니 궁극기를 쓰는 타이밍을 잘 살펴야 해요. (R)\'사냥의 전율\'로 도약하여 트런들의 방어력을 낮춘 뒤 (E)\'올가미 투척\'의 속박을 활용해 킬각을 보세요. 트런들은 (P)\'헌납\'으로 체력을 회복하므로 미니언이 많을 때는 전투를 피하세요.', item: '첫 코어로 굶주린 히드라를 가서 공격력과 생명력 흡수를 챙기세요. 신발은 트런들의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 트런들의 (W)\'얼음 왕국\'과 (P)\'헌납\'을 통한 회복을 억제하세요.' },
    '트린다미어': { lv1: '트린다미어는 (P)\'격노\'로 분노를 모아 치명타를 노리니 초반부터 정면 평타 싸움은 피하세요. 수풀에 숨어 (Q)\'포악함\'을 활용해 짧게 딜교환을 하고 다시 숨어서 트린다미어가 (Q)\'피의 갈망\'을 쓰기 어렵게 압박하세요. 첫 웨이브를 먹으며 거리 조절을 잘하는 것이 중요해요.', lv3: '야성 중첩이 쌓였을 때 (E)\'올가미 투척\'으로 트린다미어를 묶고 (Q)\'포악함\'을 이어가며 폭발적인 피해를 입히세요. 트린다미어가 (W)\'조롱의 외침\'을 사용해 공격력을 낮추면 무리하게 딜교하지 말고 (W)\'전투의 포효\'로 체력을 회복하며 버티세요. (E)\'회전 베기\'의 궤적을 잘 보고 대응해야 해요.', lv6: '(R)\'사냥의 전율\'로 위장 상태에서 도약해 방어력을 낮추고 순식간에 공격 기회를 잡으세요. 다만 트린다미어가 (R)\'불사의 분노\'를 사용하면 죽지 않으니, 궁극기 지속시간 동안은 딜을 아끼고 끝난 직후에 (E)\'올가미 투척\'을 맞춰 마무리하세요. 라인을 밀어 넣고 정글러의 개입을 유도하는 것도 좋아요.', item: '몰락한 왕의 검을 첫 코어로 가서 트린다미어와의 지속 교전 능력을 높이세요. 신발은 트린다미어의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 트린다미어가 (Q)\'피의 갈망\'을 통해 체력을 회복하는 것을 억제하세요.' },
    '티모': { lv1: '티모는 (Q)\'실명 다트\'로 시야를 가리고 (E)\'맹독 다트\'를 통해 지속 피해를 입히니 거리를 조절하며 버티세요. 수풀 속에 있으면 (P)\'유격 전투\'로 투명해질 수 있으니 항상 수풀 주변을 경계하며 미니언을 챙기세요. 초반에는 무리하게 맞붙기보다 (Q)\'포악함\'을 사용해 미니언을 빠르게 정리하며 성장하세요.', lv3: '티모의 (Q)\'실명 다트\'를 맞으면 평타가 무력해지니 다트가 빠진 타이밍을 노려 진입하세요. (E)\'올가미 투척\'을 적중시켜 둔화를 걸고 (Q)\'포악함\'으로 강화된 평타를 넣으며 딜교환을 시작하세요. 티모가 (W)\'신속한 이동\'으로 도망가려 할 때 (E)\'올가미 투척\'의 야성 효과로 제자리에 묶는 것이 중요해요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 접근하여 티모의 방어력을 낮추며 강력한 딜을 넣으세요. 라인 곳곳에 깔린 (R)\'유독성 함정\'은 밟으면 둔화와 피해를 주니 버섯 위치를 잘 확인하며 이동하세요. 티모가 (R)\'유독성 함정\'을 설치하러 라인을 비우면 빠르게 타워를 압박하며 주도권을 가져오세요.', item: '굶주린 히드라를 첫 코어로 가서 (E)\'맹독 다트\'의 지속 피해를 생명력 흡수로 버티세요. 신발은 티모의 마법 피해와 둔화를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 티모가 (W)\'신속한 이동\'으로 도망갈 때 점멸로 따라잡고 점화로 빠르게 마무리하세요.' },
    '판테온': { lv1: '판테온이 (Q)\'혜성의 창\'을 던져 견제하니 수풀에 숨어 거리를 조절하세요. (P)\'필멸자의 의지\'가 쌓인 강화 스킬이 빠진 뒤에 (Q)\'포악함\'으로 짧게 딜교환하고 빠르게 빠지세요. 수풀에서 도약해 기습적으로 공격하고 다시 숨는 방식으로 체력 손실을 최소화하세요.', lv3: '(W)\'방호의 도약\' 기절에 걸리면 스킬을 쓸 수 없으니 판테온의 진입 타이밍을 주의하세요. (E)\'방패 돌격\'이 켜진 동안은 정면 공격이 무효화되니 딜을 멈추고 끝난 뒤에 (E)\'올가미 투척\'으로 속박하세요. 기절을 맞기 전에 간격을 벌리는 것이 중요하고, (W)\'전투의 포효\'는 기절이 아닌 상황에서 군중 제어를 풀 때 쓰세요.', lv6: '(R)\'거대 유성\'이 떨어지는 지점을 빠르게 파악해 범위 밖으로 벗어나세요. (R)\'사냥의 전율\'로 위장해 다가가 판테온의 (W)\'방호의 도약\'이 빠진 타이밍에 진입해 폭딜을 넣으세요. 판테온은 궁극기로 다른 라인에 빠르게 개입하니 사라지면 즉시 핑을 찍고 라인을 관리하세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력을 보강하고 강력한 피해와 회복 능력을 챙기세요. 신발은 판테온의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 정화를 추천해요. (W)\'방호의 도약\'의 기절 효과를 정화로 빠르게 풀고 반격할 수 있어요.' },
    '피들스틱': { lv1: '수풀을 활용해 (P)\'보이지 않는 포식자\'로 접근하며 먼저 공격을 시도하세요. 피들스틱이 (Q)\'공포\'로 대응하기 전에 (Q)\'포악함\'을 사용하여 짧은 딜교환을 진행해요. 거리 조절을 통해 상대의 스킬을 피하며 성장에 집중하세요.', lv3: '(E)\'올가미 투척\'을 적중시켜 둔화를 걸고 야성을 쌓는 것이 중요해요. 피들스틱이 (E)\'수확\'을 사용하여 침묵을 거는 중심부 위치를 피하며 전투하세요. 야성이 최대일 때 (W)\'전투의 포효\'로 강화된 피해를 입히며 압박해요.', lv6: '(R)\'사냥의 전율\'로 위장 진입하여 상대의 방어력을 깎고 킬을 노리세요. 피들스틱의 (Q)\'공포\'에 걸리면 스킬을 쓸 수 없으니 사거리 안에 들어가기 전에 (Q)\'공포\' 사용 여부를 확인하세요. 피들스틱이 (R)\'까마귀 폭풍\'을 사용할 때는 위치를 옮겨 피해를 피하고, 라인을 빠르게 밀어 합류를 늦추세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 선택해요. 상대의 마법 피해에 저항하고 교전 시 안정적인 피해를 입히기 위해서예요.', spell: '점멸과 점화. 점화는 피들스틱이 (W)\'풍작\'으로 체력을 회복하는 것을 억제하고 킬을 노리기 위해서예요.' },
    '피오라': { lv1: '피오라는 (Q)\'찌르기\'로 빠르게 접근하고 (P)\'치명적인 검무\'의 급소를 가격해 체력을 회복해요. 1~2레벨에는 급소를 내주지 않도록 계속 움직이며 (Q)\'포악함\'으로 짧게 딜교환하고 빠르게 빠지세요. 피오라가 (Q)\'찌르기\'로 들어오는 타이밍에 맞춰 평타를 섞어 대응하세요.', lv3: '피오라의 (W)\'응수\'는 모든 공격과 이동 불가 효과를 막아내고 기절을 거니, (W)\'응수\'가 켜진 동안에는 (E)\'올가미 투척\'이나 (W)\'전투의 포효\'를 쓰지 마세요. (W)\'응수\'가 빠진 것을 확인한 뒤 최대 야성 상태의 (E)\'올가미 투척\'으로 속박시키고 진입하세요. (E)\'대가의 검술\'로 강화 평타를 쓰는 피오라와 정면에서 길게 싸우지 마세요.', lv6: '(R)\'사냥의 전율\'로 위장해 진입하면 방어력을 낮춰 큰 피해를 줄 수 있지만, 피오라의 (R)\'대결투\'가 켜지면 급소를 계속 피해 움직여야 해요. (W)\'응수\'가 빠진 타이밍에 (R)\'사냥의 전율\'로 도약해 폭발적인 피해를 입히고 빠르게 마무리하세요. 피오라가 사이드에서 (R)\'대결투\'로 압박할 때는 정글의 도움을 받아 함께 대응하세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력을 보충하고 타격 시 체력 회복으로 유지력을 높이세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 피오라가 (P)\'치명적인 검무\'와 (R)\'대결투\'로 회복하는 양을 점화의 치유 감소로 억제하세요.' },
    '하이머딩거': { lv1: '하이머딩거가 (Q)\'H-28 G 진화형 포탑\'을 설치해 라인 주도권을 가져가니 포탑의 공격 범위에 들어가지 않도록 주의하세요. 수풀에서 (P)\'보이지 않는 포식자\'로 도약한 뒤 (Q)\'포악함\'을 사용하여 짧게 딜교환하고 빠져나오세요.', lv3: '하이머딩거의 (E)\'CH-2 전자폭풍 수류탄\' 중앙에 맞으면 기절하니 범위를 잘 피하며 진입하세요. 상대의 스킬이 빠진 것을 확인한 뒤 (E)\'올가미 투척\'으로 하이머딩거를 묶고 (W)\'전투의 포효\'로 입은 피해를 회복하며 싸우세요.', lv6: '(R)\'사냥의 전율\'을 사용해 위장 상태로 접근하여 하이머딩거의 (R)\'업그레이드!!!\'가 빠진 타이밍에 진입하세요. 하이머딩거가 (Q)\'H-28 G 진화형 포탑\'을 깔아둔 곳은 위험하니 포탑이 없는 곳을 노려 방어력을 낮춘 뒤 처치하세요.', item: '맬모셔스의 아귀를 첫 코어로 올려 마법 저항력을 확보하고 생명선 효과로 버티세요. 신발은 하이머딩거의 (E)\'CH-2 전자폭풍 수류탄\' 기절 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 하이머딩거는 체력이 낮을 때 점화의 고정 피해로 빠르게 마무리하기 좋아요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_rengar);
if (typeof module !== 'undefined') module.exports = top_rengar;
